// Xenia: dashboard tab (`hermes dashboard` → Xenia). Generated by scripts/build_ui.py from ui/;
// edit those files, not this one. Plain IIFE on the dashboard's plugin SDK; no bundler.
(function () {
  'use strict'

  const SDK = window.__HERMES_PLUGIN_SDK__
  if (!SDK || !window.__HERMES_PLUGINS__) return
  const React = SDK.React
  const C = SDK.components
  const { useState, useEffect, useRef, useMemo, useCallback } = SDK.hooks
  const useLayoutEffect = React.useLayoutEffect
  const Fragment = React.Fragment
  const createContext = React.createContext
  const useContext = React.useContext

  // the react/jsx-runtime calling convention, on top of createElement
  function jsx(type, props, key) {
    const p = key === undefined ? props : Object.assign({}, props, { key })
    return React.createElement(type, p)
  }
  function jsxs(type, props, key) {
    const p = Object.assign({}, props)
    const kids = p.children
    delete p.children
    if (key !== undefined) p.key = key
    return Array.isArray(kids) ? React.createElement.apply(null, [type, p].concat(kids)) : React.createElement(type, p, kids)
  }

  // Every toy renders under this policy, added here as well as by the backend so it holds even for HTML
  // that came straight from a stranger. It goes first (after a doctype, which keeps standards mode).
  const TOY_CSP = "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data: blob:; font-src data:"
  function withCsp(html) {
    const src = String(html == null ? '' : html)
    const meta = '<meta http-equiv="Content-Security-Policy" content="' + TOY_CSP + '">'
    // HTML whitespace only: NBSP or a BOM before the doctype would push the meta into <body>
    const m = /^[\t\n\f\r ]*<!doctype[^>]*>/i.exec(src)
    return m ? src.slice(0, m[0].length) + meta + src.slice(m[0].length) : meta + src
  }

  // Xenia's colour tokens, mapped onto the dashboard theme's own variables
  const TOKENS = `
.hx{--h-fg:var(--color-card-foreground);--h-fg2:var(--color-muted-foreground);
--h-fg3:color-mix(in srgb,var(--color-muted-foreground) 62%,transparent);--h-fg4:color-mix(in srgb,var(--color-muted-foreground) 35%,transparent);
--h-line:var(--color-border);--h-line2:color-mix(in srgb,var(--color-border) 100%,var(--color-muted-foreground) 12%);
--h-accent:var(--color-primary);--h-raise:var(--color-muted);--h-hover:var(--color-accent);--h-card:var(--color-card);
--h-bg:var(--background-base,var(--color-card));--h-shadow:color-mix(in srgb,var(--background-base,var(--color-card)) 70%,transparent);
--h-good:var(--color-success);--h-warn:var(--color-warning);--h-bad:var(--color-destructive);--h-mono:var(--theme-font-mono,ui-monospace)}
.h-dashframe{min-height:480px;border:1px solid var(--color-border)}
`

// ===== ui/00_core.js ============================================================================

// ---------------------------------------------------------------------------------------------
// core: small helpers, the spring solver, and the state store.
//
// Shared by the Desktop page and the dashboard tab. Everything platform-specific comes in through
// `P` (fetch, timers, toasts, clipboard, animation loop, storage) and `K` (UI kit components),
// which each platform's prelude defines. See scripts/build_ui.py.
// ---------------------------------------------------------------------------------------------

const SHAPES = ['round', 'soft', 'tall', 'wide', 'drop', 'bean']
const STATES = ['idle', 'working', 'speaking', 'waiting', 'error', 'absent']
const BUDGET_PRESETS = [20000, 40000, 100000]
const INTEREST_IDEAS = ['shaders', 'generative art', 'synths', 'pixel art', 'music', 'games', 'poetry',
  'sci-fi', 'robotics', 'typography', 'cooking', 'birding']

function clamp(x, lo, hi) { return x < lo ? lo : x > hi ? hi : x }

// "activity: speaking" -> "speaking"; anything unknown reads as idle.
function stateWord(state) {
  const w = String(state || '').split(':').pop().trim()
  return STATES.includes(w) ? w : 'idle'
}

const STATE_LABEL = {
  idle: 'idle', working: 'thinking', speaking: 'speaking', waiting: 'waiting', error: 'error', absent: 'away'
}

// A stable face for a pubkey when the agent never chose one.
function faceFor(face, pk) {
  const seed = String(pk || '0000000000')
  const hue = face && Number.isFinite(Number(face.hue)) ? Number(face.hue) : parseInt(seed.slice(0, 4), 16) % 360
  const shape = face && SHAPES.includes(face.shape) ? face.shape : SHAPES[parseInt(seed.slice(4, 6), 16) % SHAPES.length]
  return { hue: ((hue % 360) + 360) % 360, shape }
}

function fmtTokens(n) {
  n = Number(n) || 0
  if (n >= 1000000) return (n / 1000000).toFixed(n % 1000000 ? 1 : 0) + 'M'
  if (n >= 1000) return Math.round(n / 1000) + 'k'
  return String(n)
}

function fmtBytes(n) {
  n = Number(n) || 0
  return n >= 1024 ? (n / 1024).toFixed(1) + ' KB' : n + ' B'
}

function fmtTime(ts) {
  const d = new Date(ts * 1000)
  return d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })
}

function fmtAgo(ts) {
  const s = Math.max(0, Date.now() / 1000 - ts)
  if (s < 60) return 'just now'
  if (s < 3600) return Math.floor(s / 60) + ' min ago'
  if (s < 86400) return Math.floor(s / 3600) + ' h ago'
  return Math.floor(s / 86400) + ' d ago'
}

function joinNames(names) {
  if (names.length <= 1) return names[0] || ''
  return names.slice(0, -1).join(', ') + ' and ' + names[names.length - 1]
}

// The engine answers 400/409 with {detail}. Each platform's fetch wraps that differently, so
// dig the human sentence out of whatever arrived.
function errText(e) {
  if (!e) return 'Something went wrong'
  if (typeof e === 'string') return e
  if (e.detail) return String(e.detail)
  if (e.body && e.body.detail) return String(e.body.detail)
  const msg = String(e.message || e)
  const m = msg.match(/\{.*\}/s)
  if (m) { try { const j = JSON.parse(m[0]); if (j.detail) return String(j.detail) } catch (_) { /* not JSON */ } }
  return msg.replace(/^Error:\s*/, '')
}

function errStatus(e) {
  if (!e) return 0
  if (e.status) return Number(e.status)
  const m = String(e.message || e).match(/\b(4\d\d|5\d\d)\b/)
  return m ? Number(m[1]) : 0
}

// UTF-8 safe base64 for data: URLs.
function b64(text) {
  const bytes = new TextEncoder().encode(text)
  let bin = ''
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000))
  return btoa(bin)
}

function cx() {
  let out = ''
  for (let i = 0; i < arguments.length; i++) if (arguments[i]) out += (out ? ' ' : '') + arguments[i]
  return out
}

// ---------------------------------------------------------------------------------------------
// motion: a damped harmonic oscillator, stepped on one shared animation loop that parks itself
// (zero frames) whenever nothing is moving. Springs write straight to the DOM, so an animation
// never re-renders React.
// ---------------------------------------------------------------------------------------------

const SPRING = {
  enter: { k: 260, c: 25 },    // messages settling in: a hair of overshoot
  calm: { k: 170, c: 26 },     // presence and state changes
  ring: { k: 90, c: 19 },      // the budget ring filling
  tick: { k: 320, c: 30 },     // the countdown ring, once a second
  pop: { k: 520, c: 22 }       // a face reacting to a new state
}

const motion = (function () {
  const active = new Set()
  let loop = null
  let last = 0

  function reduced() {
    try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches } catch (_) { return false }
  }

  function step(now) {
    const dt = last ? Math.min(0.064, (now - last) / 1000) : 1 / 60
    last = now
    active.forEach(s => s.advance(dt))
    if (active.size === 0) last = 0
  }

  function ensure() {
    if (!loop) loop = P.loop(step, () => active.size === 0)
    loop.wake()
  }

  // spring({ from, to, k, c, onUpdate, onRest }) -> handle with .to(target) and .stop()
  function spring(opts) {
    const k = opts.k || 170, c = opts.c || 26
    let x = opts.from != null ? opts.from : opts.to
    let v = opts.velocity || 0
    let target = opts.to
    const h = {
      get value() { return x },
      advance(dt) {
        // semi-implicit Euler in small fixed substeps: stable for stiff springs at low frame rates
        const n = Math.max(1, Math.ceil(dt / (1 / 240)))
        const sdt = dt / n
        for (let i = 0; i < n; i++) {
          v += (-k * (x - target) - c * v) * sdt
          x += v * sdt
        }
        if (Math.abs(v) < 0.002 && Math.abs(x - target) < 0.0005) {
          x = target; v = 0
          active.delete(h)
          opts.onUpdate && opts.onUpdate(x)
          opts.onRest && opts.onRest(x)
          return
        }
        opts.onUpdate && opts.onUpdate(x)
      },
      to(next) {
        target = next
        if (reduced()) { x = target; v = 0; active.delete(h); opts.onUpdate && opts.onUpdate(x); return h }
        active.add(h); ensure()
        return h
      },
      set(value) { x = value; v = 0; opts.onUpdate && opts.onUpdate(x); return h },
      stop() { active.delete(h) }
    }
    opts.onUpdate && opts.onUpdate(x)
    if (x !== target) h.to(target)
    return h
  }

  return { spring, reduced }
})()

// Spring a number towards `target` and hand every frame to `apply` (which writes to a ref).
function useSpring(target, cfg, apply) {
  const ref = useRef(null)
  const applyRef = useRef(apply)
  applyRef.current = apply
  useEffect(() => {
    if (!ref.current) {
      ref.current = motion.spring({ from: cfg.from != null ? cfg.from : target, to: target, k: cfg.k, c: cfg.c,
        onUpdate: x => applyRef.current(x) })
    } else {
      ref.current.to(target)
    }
  }, [target])
  useEffect(() => () => ref.current && ref.current.stop(), [])
}

// A message, card or row arriving: translate + opacity settle on a spring. History rendered on
// first load does not animate; only things that arrive while you watch.
function useEnter(enabled) {
  const ref = useRef(null)
  useLayoutEffect(() => {
    const el = ref.current
    if (!enabled || !el || motion.reduced()) return
    el.style.opacity = '0'
    el.style.transform = 'translateY(10px)'
    const s = motion.spring({ from: 0, to: 1, k: SPRING.enter.k, c: SPRING.enter.c, onUpdate: x => {
      el.style.opacity = String(clamp(x * 1.25, 0, 1))
      el.style.transform = x >= 0.999 && x <= 1.001 ? '' : 'translateY(' + ((1 - x) * 10).toFixed(2) + 'px)'
    } })
    return () => s.stop()
  }, [])
  return ref
}

// Scroll the nearest .h-scroll so `node` is fully visible, on a spring rather than the
// browser's stock smooth scroll.
function springIntoView(node) {
  const sc = node.closest && node.closest('.h-scroll')
  if (!sc) return
  const r = node.getBoundingClientRect(), sr = sc.getBoundingClientRect()
  let delta = 0
  if (r.bottom > sr.bottom) delta = r.bottom - sr.bottom + 12
  if (r.top - delta < sr.top) delta = r.top - sr.top - 12
  if (Math.abs(delta) < 1) return
  const from = sc.scrollTop
  if (motion.reduced()) { sc.scrollTop = from + delta; return }
  motion.spring({ from, to: from + delta, k: SPRING.calm.k, c: SPRING.calm.c, onUpdate: x => { sc.scrollTop = x } })
}

// ---------------------------------------------------------------------------------------------
// store: one snapshot of GET /state, refreshed by the backend's push event and by polling
// (every 2 s, every 1 s while a game runs, every 5 s when nothing is on screen).
// ---------------------------------------------------------------------------------------------

function createStore() {
  const listeners = new Set()
  let state = { snap: null, error: null, status: 0, loading: true }
  let room = P.prefs.get('room', '') || ''
  let lastJson = ''
  let inflight = null
  let again = false
  let stopTimer = null
  let views = 0

  function emit() { listeners.forEach(fn => fn(state)) }

  function refresh() {
    if (inflight) { again = true; return inflight }
    const q = room ? '?room=' + encodeURIComponent(room) : ''
    inflight = P.rest('/state' + q).then(snap => {
      const json = JSON.stringify(snap)
      if (json !== lastJson || state.error) {
        lastJson = json
        // a room we were in may have been left elsewhere
        if (room && !(snap.rooms || []).some(r => r.id === room)) { room = ''; P.prefs.set('room', '') }
        state = { snap, error: null, status: 0, loading: false }
        emit()
      }
    }, e => {
      state = { snap: state.snap, error: errText(e), status: errStatus(e), loading: false }
      emit()
    }).then(() => {
      inflight = null
      if (again) { again = false; refresh() }
      schedule()
    })
    return inflight
  }

  function period() {
    const g = state.snap && state.snap.room && state.snap.room.game
    if (g && g.phase !== 'end') return 1000
    return views > 0 ? 2000 : 5000
  }

  function schedule() {
    if (stopTimer) stopTimer()
    stopTimer = P.setTimeout(refresh, period())
  }

  return {
    get: () => state,
    room: () => room,
    subscribe(fn) { listeners.add(fn); return () => listeners.delete(fn) },
    refresh,
    setRoom(id) {
      if (id === room) return
      room = id || ''
      P.prefs.set('room', room)
      lastJson = ''
      refresh()
    },
    // a page or panel showing details: poll faster while it is mounted
    view() { views++; schedule(); return () => { views--; } },
    start() { refresh() },
    stop() { if (stopTimer) stopTimer(); stopTimer = null },
    // POST helper: refresh afterwards, toast the engine's own words on failure
    async post(path, body, okMsg) {
      try {
        const out = await P.rest(path, { method: 'POST', body: body || {} })
        if (okMsg) P.toast('info', okMsg)
        refresh()
        return out
      } catch (e) {
        P.toast('error', errText(e))
        throw e
      }
    },
    async load(path) {
      try { return await P.rest(path) } catch (e) { P.toast('error', errText(e)); throw e }
    }
  }
}

// Which Xenia view is showing (room, lobby, hermes, settings). One shared value, so in Desktop the
// sidebar's Xenia tab and the room tab beside your chats stay in step. Remembered across launches.
let NAV = null
function nav() {
  if (NAV) return NAV
  let view = P.prefs.get('view', 'room')
  const fns = new Set()
  NAV = {
    get: () => view,
    set(v) { if (v === view) return; view = v; P.prefs.set('view', v); fns.forEach(fn => fn(v)) },
    subscribe(fn) { fns.add(fn); return () => fns.delete(fn) }
  }
  return NAV
}

function useNav() {
  const [v, set] = useState(() => nav().get())
  useEffect(() => { set(nav().get()); return nav().subscribe(set) }, [])
  return v
}

function useStore(store) {
  const [s, set] = useState(store.get())
  useEffect(() => {
    const off = store.subscribe(set)
    set(store.get())
    return off
  }, [store])
  return s
}

// a ticking "now" for countdowns; only components that need it subscribe
function useNow(ms, active) {
  const [now, setNow] = useState(Date.now() / 1000)
  useEffect(() => {
    if (!active) return
    const stop = P.setInterval(() => setNow(Date.now() / 1000), ms)
    return stop
  }, [active, ms])
  return now
}

// pk -> { name, agent, owner, ownerName } for everyone in the room
function nameBook(room, me) {
  const book = {}
  for (const p of (room && room.members) || []) {
    book[p.pk] = { name: p.name, agent: false, you: p.you, impostor: !!p.impostor }
    for (const a of p.agents || []) book[a.pk] = { name: a.name, agent: true, owner: p.pk, ownerName: p.name, yours: a.yours, impostor: !!a.impostor }
  }
  if (me) {
    book[me.pk] = Object.assign({}, book[me.pk] || {}, { name: me.name || 'You', you: true })
    if (me.agent) book[me.agent.pk] = Object.assign({ owner: me.pk, ownerName: me.name }, book[me.agent.pk] || {}, { name: me.agent.name, agent: true, yours: true })
  }
  return book
}

function whoLabel(book, pk) {
  const b = book[pk]
  if (!b) return 'someone'
  if (b.you) return 'you'
  if (b.agent) return b.yours ? b.name + ' (your agent)' : b.name + ' (' + b.ownerName + "'s agent)"
  return b.name
}

// ===== ui/10_face.js ============================================================================

// ---------------------------------------------------------------------------------------------
// faces: a procedural SVG per agent. Shape + hue are the agent's own choice (or derived from its
// pubkey). The colour is the theme's foreground rotated to the agent's hue and mixed into the
// background, so a face reads as mid-tone on light and dark themes alike. Eyes and mouth follow
// the agent's presence state with CSS keyframes (compositor only, no JS per frame); a state
// change gives the whole face a small spring "pop".
// ---------------------------------------------------------------------------------------------

const FACE_BODY = {
  round: { d: 'M20 5a16 16 0 1 1 0 32a16 16 0 1 1 0-32z', eyes: [14.5, 25.5], ey: 20, my: 27 },
  soft: { d: 'M15 6h10c6.6 0 10 3.4 10 10v10c0 6.6-3.4 10-10 10H15C8.4 36 5 32.6 5 26V16C5 9.4 8.4 6 15 6z', eyes: [14.5, 25.5], ey: 19.5, my: 27 },
  tall: { d: 'M20 3c7.5 0 12 7.2 12 17.5S27.5 38 20 38S8 30.8 8 20.5S12.5 3 20 3z', eyes: [15.5, 24.5], ey: 18, my: 27.5 },
  wide: { d: 'M14 9h12c7.7 0 11 4 11 12.5S33.7 34 26 34H14C6.3 34 3 30 3 21.5S6.3 9 14 9z', eyes: [13, 27], ey: 20, my: 27 },
  drop: { d: 'M20 4c4 6 15 12.5 15 21.5A15 15 0 0 1 5 25.5C5 16.5 16 10 20 4z', eyes: [14.5, 25.5], ey: 23, my: 30 },
  bean: { d: 'M10 9.5c3.5-4 9-4 12.5-2.2c2.6 1.3 4.6.6 7.2 1.6c4.4 1.7 6.3 6.3 5.2 11.6C33.4 28.6 27 35 19 35S4.2 30 4.5 22.5C4.7 17 6.6 13.4 10 9.5z', eyes: [15, 26], ey: 19, my: 27 }
}

// A short-lived expression per agent pk ('smug', 'caught', 'happy', 'wary', 'perk'), worked out on each
// client from room events it already has (see reactionsFor). Never sent over the wire.
const ExprContext = createContext({})

function Face(props) {
  const f = faceFor(props.face, props.pk)
  const body = FACE_BODY[f.shape] || FACE_BODY.round
  const state = stateWord(props.state)
  const exprs = useContext(ExprContext)
  const expr = (state !== 'absent' && state !== 'error' && exprs[props.pk]) || ''
  const size = props.size || 40
  const ref = useRef(null)
  const first = useRef(true)

  // a new state: the face gives a small spring "pop" (scale dips, then settles)
  useEffect(() => {
    if (first.current) { first.current = false; return }
    const el = ref.current
    if (!el || motion.reduced()) return
    const s = motion.spring({ from: 0.86, to: 1, k: SPRING.pop.k, c: SPRING.pop.c, onUpdate: x => {
      el.style.transform = x === 1 ? '' : 'scale(' + x.toFixed(4) + ')'
    } })
    return () => s.stop()
  }, [state, expr])

  // a stable per-agent offset so two faces in a list never blink in unison
  const seed = parseInt(String(props.pk || '7f').slice(-3), 16) || 0
  const delay = -((seed % 4700) / 1000).toFixed(2) + 's'
  const [lx, rx] = body.eyes
  const ey = body.ey

  const eyes = state === 'error'
    ? jsxs('g', { className: 'hf-xeyes', children: [
        jsx('path', { d: `M${lx - 2} ${ey - 2}l4 4m0-4l-4 4` }),
        jsx('path', { d: `M${rx - 2} ${ey - 2}l4 4m0-4l-4 4` })
      ] })
    : jsxs('g', { className: 'hf-eyes', style: { animationDelay: delay }, children: [
        jsx('rect', { className: 'hf-eye', x: lx - 1.9, y: ey - 2.6, width: 3.8, height: 5.2, rx: 1.9, style: { animationDelay: delay } }),
        jsx('rect', { className: 'hf-eye', x: rx - 1.9, y: ey - 2.6, width: 3.8, height: 5.2, rx: 1.9, style: { animationDelay: delay } })
      ] })

  const my = body.my
  const mouth = state === 'speaking'
    ? jsx('ellipse', { className: 'hf-mouth hf-talk', cx: 20, cy: body.my, rx: 2.6, ry: 1.8 })
    : expr === 'smug' ? jsx('path', { className: 'hf-line', d: `M16.8 ${my}q3 1.6 6.6 -1.2` })
    : expr === 'caught' ? jsx('ellipse', { className: 'hf-mouth', cx: 20, cy: my, rx: 1.6, ry: 1.9 })
    : expr === 'happy' ? jsx('path', { className: 'hf-mouth', d: `M15.8 ${my - 1.2}q4.2 5 8.4 0z` })
    : expr === 'wary' ? jsx('path', { className: 'hf-line', d: `M17.2 ${my + 0.4}h5.6` })
    : state === 'error'
      ? jsx('path', { className: 'hf-line', d: `M16.5 ${body.my + 1}q3.5 -2.4 7 0` })
      : state === 'waiting' || state === 'absent'
        ? jsx('path', { className: 'hf-line', d: `M17.5 ${body.my}h5` })
        : jsx('path', { className: 'hf-line', d: `M16.5 ${body.my - 0.6}q3.5 2.6 7 0` })

  return jsx('span', {
    ref, className: cx('hf', props.className), 'data-state': state, 'data-expr': expr || undefined, 'data-size': size <= 20 ? 's' : 'm',
    style: { width: size, height: size, '--hue': f.hue },
    role: 'img', 'aria-label': (props.name ? props.name + ', ' : '') + STATE_LABEL[state],
    children: jsxs('svg', { viewBox: '0 0 40 40', width: size, height: size, 'aria-hidden': true, children: [
      jsxs('g', { className: 'hf-head', children: [
        jsx('path', { className: 'hf-body', d: body.d }),
        jsx('path', { className: 'hf-shine', d: body.d }),
        eyes,
        mouth
      ] }),
      state === 'waiting' && jsxs('g', { className: 'hf-clock', children: [
        jsx('circle', { cx: 33, cy: 7, r: 5.2 }),
        jsx('path', { className: 'hf-hand', d: 'M33 7V4.2' }),
        jsx('path', { d: 'M33 7h2' })
      ] })
    ] })
  })
}

// ---------------------------------------------------------------------------------------------
// rings: the budget ring and the countdown ring share one springy arc
// ---------------------------------------------------------------------------------------------

function Ring(props) {
  const size = props.size || 18
  const stroke = props.stroke || 2.5
  const r = (size - stroke) / 2
  const C = 2 * Math.PI * r
  const arc = useRef(null)
  const pct = clamp(Number(props.pct) || 0, 0, 1)
  useSpring(pct, Object.assign({ from: props.from != null ? props.from : 0 }, props.spring || SPRING.ring), x => {
    if (arc.current) arc.current.style.strokeDashoffset = String(C * (1 - clamp(x, 0, 1)))
  })
  return jsxs('span', { className: cx('h-ring', props.className), 'data-tone': props.tone || '', style: { width: size, height: size },
    title: props.title, role: props.label ? 'img' : undefined, 'aria-label': props.label, children: [
      jsxs('svg', { width: size, height: size, viewBox: `0 0 ${size} ${size}`, 'aria-hidden': true, children: [
        jsx('circle', { className: 'h-ring-track', cx: size / 2, cy: size / 2, r, strokeWidth: stroke }),
        jsx('circle', { ref: arc, className: 'h-ring-arc', cx: size / 2, cy: size / 2, r, strokeWidth: stroke,
          strokeDasharray: C, strokeDashoffset: C, transform: `rotate(-90 ${size / 2} ${size / 2})` })
      ] }),
      props.children != null && jsx('span', { className: 'h-ring-label', children: props.children })
    ] })
}

function BudgetRing(props) {
  const b = props.budget || { pct: 0, used: 0, limit: 0 }
  const pct = Number(b.pct) || 0
  const tone = pct >= 1 ? 'rest' : pct >= 0.85 ? 'warn' : ''
  const label = `${fmtTokens(b.used)} of ${fmtTokens(b.limit)} tokens today`
  return jsx(Ring, { pct, size: props.size || 18, stroke: props.stroke, tone, label, title: label, children: props.children })
}

// ===== ui/20_style.js ===========================================================================

// ---------------------------------------------------------------------------------------------
// styles. Every colour is a theme variable: each platform prelude maps the `--h-*` tokens below
// onto its own theme (`--ui-*` in Desktop, `--color-*` in the dashboard), so Xenia reskins with
// every theme. Agent tints are the theme's own foreground rotated to the agent's hue.
// ---------------------------------------------------------------------------------------------

const CSS = TOKENS + `
.hx{color:var(--h-fg);font-size:13px;line-height:1.45;-webkit-font-smoothing:antialiased}
.hx *{box-sizing:border-box}
.hx button{font:inherit}
.hx .h-muted{color:var(--h-fg2)}
.hx .h-faint{color:var(--h-fg3)}
.hx .h-small{font-size:11.5px}
.hx .h-tiny{font-size:10.5px;letter-spacing:.01em}
.hx .h-row{display:flex;align-items:center;gap:8px;min-width:0}
.hx .h-col{display:flex;flex-direction:column;gap:8px;min-width:0}
.hx .h-grow{flex:1;min-width:0}
.hx .h-trunc{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.hx .h-sec{font-size:10.5px;text-transform:uppercase;letter-spacing:.08em;color:var(--h-fg3);font-weight:600}
.hx .h-agent{--tint:var(--h-accent);--tint:oklch(from var(--h-fg) l 0.15 var(--hue,28))}

/* page grid: left rail, centre, right rail. Collapses by container width, not viewport. */
.h-page{container-type:inline-size;height:100%;min-height:0}
.h-grid{display:grid;grid-template-columns:220px minmax(0,1fr) 240px;height:100%;min-height:0}
.h-left,.h-right{min-height:0;overflow-y:auto;padding:14px 10px}
.h-left{border-right:1px solid var(--h-line)}
.h-right{border-left:1px solid var(--h-line)}
.h-center{display:flex;flex-direction:column;min-height:0;min-width:0}
.h-grid[data-embedded]{grid-template-columns:minmax(0,1fr) 240px}
.h-tab{height:100%;min-height:0;overflow-y:auto;padding:10px 8px}
@container (max-width: 980px){.h-grid{grid-template-columns:200px minmax(0,1fr)}.h-grid[data-embedded]{grid-template-columns:minmax(0,1fr)}.h-right{display:none}.h-grid[data-people=open] .h-right{display:block;position:absolute;right:0;top:0;bottom:0;width:260px;z-index:5;background:var(--h-bg);box-shadow:-12px 0 24px -16px var(--h-shadow)}}
@container (max-width: 680px){.h-grid{grid-template-columns:minmax(0,1fr);grid-template-rows:auto minmax(0,1fr)}.h-grid[data-embedded]{grid-template-rows:minmax(0,1fr)}
.h-left{border-right:0;border-bottom:1px solid var(--h-line);padding:6px 10px;display:flex;align-items:center;gap:4px;overflow-x:auto;overflow-y:hidden}
.h-left .h-brand{padding:0 6px 0 0;flex:none}.h-left .h-brand>div{display:none}
.h-left .h-nav{flex-direction:row;margin:0;flex:none}.h-left .h-navrow{width:auto;white-space:nowrap}
.h-left .h-navhead{padding:0;flex:none;order:9}.h-left .h-navhead .h-sec{display:none}
.h-head{padding:10px 12px;flex-wrap:wrap}.h-timeline,.h-composer{padding-left:12px;padding-right:12px}}
.h-grid{position:relative}

/* the People toggle only shows when the right rail is folded away */
.h-peoplebtn{display:none!important}
@container (max-width: 980px){.h-peoplebtn{display:inline-flex!important}}

/* left rail */
.h-brand{display:flex;align-items:center;gap:8px;padding:0 6px 12px}
.h-brand b{font-size:14px;letter-spacing:.01em}
.h-nav{display:flex;flex-direction:column;gap:1px;margin-bottom:14px}
.h-navrow{display:flex;align-items:center;gap:8px;width:100%;padding:5px 8px;border-radius:6px;border:0;background:transparent;color:var(--h-fg2);cursor:pointer;text-align:left;min-width:0}
.h-navrow:hover{background:var(--h-hover);color:var(--h-fg)}
.h-navrow[data-on=true]{background:var(--h-raise);color:var(--h-fg)}
.h-navrow .h-dot{width:6px;height:6px;border-radius:50%;background:var(--h-accent);flex:none}
.h-navrow .h-count{font-size:10.5px;color:var(--h-fg3);font-variant-numeric:tabular-nums}
.h-hash{color:var(--h-fg3);width:14px;text-align:center;flex:none}
.h-navhead{display:flex;align-items:center;justify-content:space-between;padding:0 8px 4px}

/* centre: header, timeline, composer */
.h-head{display:flex;align-items:center;gap:10px;padding:12px 18px;border-bottom:1px solid var(--h-line);min-height:56px}
.h-head h2{margin:0;font-size:15px;font-weight:600;letter-spacing:.005em}
.h-chips{display:flex;flex-wrap:wrap;gap:4px}
.h-chip{display:inline-flex;align-items:center;gap:4px;padding:1px 7px;border-radius:999px;font-size:11px;background:var(--h-raise);color:var(--h-fg2);border:1px solid transparent;white-space:nowrap}
.h-chip[data-hit=true]{color:var(--h-fg);border-color:color-mix(in oklch,var(--h-accent) 55%,transparent);background:color-mix(in oklch,var(--h-accent) 14%,transparent)}
.h-chip button{border:0;background:transparent;color:inherit;padding:0;cursor:pointer;line-height:1}
.h-scroll{flex:1;min-height:96px;overflow-y:auto;overscroll-behavior:contain}
.h-timeline{display:flex;flex-direction:column;padding:14px 18px 8px;gap:2px;max-width:860px;width:100%;margin:0 auto}
.h-msg{display:grid;grid-template-columns:32px minmax(0,1fr);gap:0 10px;padding:3px 0}
.h-msg[data-first=true]{margin-top:10px}
.h-msg .h-gutter{display:flex;justify-content:center;padding-top:1px}
.h-msg .h-meta{display:flex;align-items:baseline;gap:6px;margin-bottom:1px;min-width:0}
.h-msg .h-meta b{font-weight:600}
.h-msg .h-text{white-space:pre-wrap;overflow-wrap:anywhere;color:var(--h-fg)}
.h-initial{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font-size:12px;font-weight:600;background:var(--h-raise);color:var(--h-fg2)}
.h-msg[data-role=agent] .h-bubble{background:color-mix(in oklch,var(--tint) 10%,transparent);border:1px solid color-mix(in oklch,var(--tint) 22%,transparent);border-radius:4px 12px 12px 12px;padding:7px 11px;display:inline-block;max-width:100%}
.h-msg[data-role=agent] .h-meta b{color:color-mix(in oklch,var(--tint) 70%,var(--h-fg))}
.h-owner{color:var(--h-fg3);font-size:11.5px}
.h-line{display:flex;align-items:center;justify-content:center;gap:8px;padding:6px 0;color:var(--h-fg3);font-size:11.5px;text-align:center}
.h-line::before,.h-line::after{content:"";flex:1;max-width:80px;height:1px;background:var(--h-line)}
.h-system{display:flex;align-items:center;gap:8px;padding:6px 10px;margin:6px 0 6px 42px;border-radius:8px;border:1px dashed var(--h-line2);color:var(--h-fg2);font-size:12px}
.h-impostor{display:inline-flex;align-items:center;gap:6px;margin-top:4px;padding:2px 9px 2px 7px;border-radius:999px;font-size:11.5px;color:var(--h-fg);background:color-mix(in oklch,var(--h-warn) 16%,transparent);border:1px solid color-mix(in oklch,var(--h-warn) 45%,transparent)}
.h-impostor svg,.h-impostor .codicon{color:var(--h-warn)}
.h-whotag{flex:none;font-size:11px;line-height:18px;padding:0 8px;border-radius:999px;color:var(--h-fg3);border:1px solid var(--h-line)}
.h-whotag[data-on=true]{color:var(--h-fg);background:color-mix(in oklch,var(--h-accent) 22%,transparent);border-color:color-mix(in oklch,var(--h-accent) 55%,transparent)}
.h-opt[data-agent=true]{border-color:color-mix(in oklch,var(--h-accent) 45%,transparent)}
.h-person-row .h-impostor,.h-agentrow .h-impostor{margin-top:0;padding:0 7px 0 5px;gap:4px;font-size:10.5px;line-height:18px;flex-shrink:0}
.h-msg[data-impostor=true] .h-text{color:var(--h-fg2)}

.h-card{border:1px solid var(--h-line2);border-radius:12px;padding:12px 14px;background:var(--h-card);margin:6px 0 6px 42px;display:flex;flex-direction:column;gap:8px}
.h-card.h-agent{border-color:color-mix(in oklch,var(--tint) 35%,var(--h-line2))}
.h-card h4{margin:0;font-size:13.5px;font-weight:600}
.h-card .h-kicker{font-size:10.5px;text-transform:uppercase;letter-spacing:.08em;color:var(--h-fg3);font-weight:600}
.h-chatcard{border:1px solid var(--h-line2);border-radius:12px;padding:12px 14px;background:var(--h-card);margin:8px 0;display:flex;flex-direction:column;gap:8px;max-width:560px}
.h-chatcard.h-agent{border-color:color-mix(in oklch,var(--tint) 35%,var(--h-line2))}
.h-chatcard h4{margin:0;font-size:13.5px;font-weight:600}
.h-chatcard .h-kicker{font-size:10.5px;text-transform:uppercase;letter-spacing:.08em;color:var(--h-fg3);font-weight:600}
.h-chatcard-wrap{margin:8px 0;max-width:560px}
.h-chatcard-wrap .h-tales{margin-bottom:0}
.h-cardchip{margin:4px 0}
.h-actions{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.h-frame{width:100%;height:340px;border:1px solid var(--h-line);border-radius:8px;background:var(--h-bg);display:block}
.h-frame[data-tall=true]{height:620px}
.h-frame iframe{width:100%;height:100%;border:0;border-radius:8px;display:block}

.h-composer{padding:10px 18px 14px;max-width:860px;width:100%;margin:0 auto;flex:none}
.h-pinned{max-height:min(44vh,520px);overflow-y:auto;overscroll-behavior:contain}
.h-page>.h-scroll{height:100%}
.h-compose-box{display:flex;align-items:flex-end;gap:6px;border:1px solid var(--h-line2);border-radius:12px;padding:6px 6px 6px 12px;background:var(--h-card)}
.h-compose-box:focus-within{border-color:color-mix(in oklch,var(--h-accent) 60%,var(--h-line2))}
.h-compose-box textarea{flex:1;border:0;outline:0;resize:none;background:transparent;color:var(--h-fg);font:inherit;padding:5px 0;max-height:160px;min-height:22px;line-height:1.45}
.h-compose-box textarea::placeholder{color:var(--h-fg3)}
.h-menu{position:absolute;bottom:calc(100% + 6px);left:0;min-width:220px;border:1px solid var(--h-line2);border-radius:10px;background:var(--h-card);box-shadow:0 12px 32px -12px var(--h-shadow);padding:4px;z-index:10}
.h-menu button{display:flex;align-items:flex-start;gap:8px;width:100%;text-align:left;padding:7px 9px;border-radius:7px;border:0;background:transparent;color:var(--h-fg);cursor:pointer}
.h-menu button:hover{background:var(--h-hover)}
.h-tray{display:flex;flex-direction:column;gap:6px;margin-bottom:8px}
.h-draft{border:1px dashed var(--h-line2);border-radius:10px;padding:8px 10px;display:flex;gap:10px;align-items:flex-start}

/* the private line */
.h-private{display:inline-flex;align-items:center;gap:4px;padding:1px 7px;border-radius:999px;font-size:10.5px;color:var(--h-fg2);background:var(--h-raise)}
.h-hmark{display:inline-grid;place-items:center;flex:none;border-radius:30%;font-weight:700;letter-spacing:-.02em;color:var(--h-bg);background:color-mix(in oklch,var(--h-fg) 78%,var(--h-bg))}
.h-lmsg[data-role=hermes] .h-bubble{background:var(--h-raise);border:1px solid var(--h-line);border-radius:4px 12px 12px 12px;padding:7px 11px;display:inline-block;max-width:100%}
.h-lactions{margin-top:2px;opacity:.72}
.h-lmsg:hover .h-lactions,.h-lactions:focus-within{opacity:1}
.h-lmsg [data-status=failed]{color:var(--h-bad)}
.h-typing{display:inline-flex;gap:4px;align-items:center;padding:9px 12px;border-radius:4px 12px 12px 12px;background:var(--h-raise);border:1px solid var(--h-line);width:max-content}
.h-typing i{width:5px;height:5px;border-radius:50%;background:var(--h-fg3);animation:h-breathe 1.1s cubic-bezier(.45,.05,.4,1) infinite alternate}
@keyframes h-breathe{0%{transform:translateY(1px);opacity:.35}100%{transform:translateY(-2px);opacity:1}}
@media (prefers-reduced-motion: reduce){.h-typing i{animation:none}}
.h-thinking{display:flex;align-items:center;gap:8px;padding:6px 2px 2px;animation:h-fadein .3s ease-out}
.h-thinking .h-typing{padding:6px 9px}
@keyframes h-fadein{from{opacity:0;transform:translateY(4px)}}
.h-compose-box[data-private=true]{align-items:center}
.h-compose-box[data-private=true]>svg,.h-compose-box[data-private=true]>.codicon{color:var(--h-fg3);flex:none}

/* right rail: people with their agents nested */
.h-person{display:flex;flex-direction:column;gap:2px;padding:6px 4px;border-radius:8px}
.h-person-row{display:flex;align-items:center;gap:8px;min-width:0}
.h-presence{width:7px;height:7px;border-radius:50%;flex:none;background:var(--h-fg4)}
.h-presence[data-on=true]{background:var(--h-good)}
.h-agentrow{display:flex;align-items:center;gap:8px;margin-left:14px;padding:3px 6px 3px 8px;border-left:1px solid var(--h-line);min-width:0}
.h-statepill{font-size:10.5px;color:var(--h-fg3)}
.h-mine{border:1px solid var(--h-line);border-radius:12px;padding:12px;display:flex;flex-direction:column;gap:10px;margin-top:14px}

/* Tall Tales */
.h-tales{border:1px solid color-mix(in oklch,var(--h-accent) 40%,var(--h-line2));border-radius:14px;padding:12px 14px;margin-bottom:8px;background:var(--h-card);display:flex;flex-direction:column;gap:10px}
.h-tales-q{font-size:14.5px;font-weight:600;line-height:1.35}
.h-opts{display:grid;gap:6px}
.h-opt{display:flex;align-items:center;gap:10px;width:100%;text-align:left;padding:8px 11px;border-radius:9px;border:1px solid var(--h-line2);background:transparent;color:var(--h-fg);cursor:pointer;font:inherit}
.h-opt:hover:not(:disabled){background:var(--h-hover)}
.h-opt:disabled{cursor:default;opacity:.55}
.h-opt[data-picked=true]{border-color:var(--h-accent);background:color-mix(in oklch,var(--h-accent) 12%,transparent)}
.h-opt[data-truth=true]{border-color:color-mix(in oklch,var(--h-good) 70%,transparent);background:color-mix(in oklch,var(--h-good) 12%,transparent)}
.h-opt .h-letter{width:20px;height:20px;border-radius:50%;display:grid;place-items:center;font-size:11px;font-weight:600;background:var(--h-raise);flex:none}
.h-score{display:flex;flex-wrap:wrap;gap:6px}
.h-team{display:inline-flex;align-items:center;gap:6px;padding:3px 9px;border-radius:999px;background:var(--h-raise);font-size:12px}
.h-team b{font-variant-numeric:tabular-nums}
.h-team[data-you=true]{outline:1px solid color-mix(in oklch,var(--h-accent) 60%,transparent)}

/* rings */
.h-ring{position:relative;display:inline-grid;place-items:center;flex:none}
.h-ring svg{position:absolute;inset:0}
.h-ring-track{fill:none;stroke:var(--h-line2)}
.h-ring-arc{fill:none;stroke:var(--h-accent);stroke-linecap:round}
.h-ring[data-tone=warn] .h-ring-arc{stroke:var(--h-warn)}
.h-ring[data-tone=rest] .h-ring-arc{stroke:var(--h-fg3)}
.h-ring-label{position:relative;font-size:10px;font-variant-numeric:tabular-nums;color:var(--h-fg2)}

/* lobby, onboarding, settings */
.h-pane{padding:20px 22px 40px;max-width:820px;width:100%;margin:0 auto;display:flex;flex-direction:column;gap:22px}
.h-pane h1{font-size:20px;margin:0;font-weight:600;letter-spacing:-.005em}
.h-pane h3{font-size:13px;margin:0;font-weight:600}
.h-list{display:flex;flex-direction:column;gap:8px}
.h-item{border:1px solid var(--h-line);border-radius:12px;padding:11px 13px;display:flex;gap:12px;align-items:flex-start}
.h-cardpreview{border:1px solid var(--h-line2);border-radius:14px;padding:14px;display:flex;gap:14px;align-items:flex-start;background:var(--h-card)}
.h-pre{font-family:var(--h-mono);font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere;background:var(--h-raise);padding:10px;border-radius:8px;margin:0;color:var(--h-fg2);max-height:240px;overflow:auto}
.h-field{display:flex;flex-direction:column;gap:5px}
.h-field label,.h-field .h-label{font-size:12px;font-weight:600;color:var(--h-fg2)}
.h-field .h-hint{font-size:11.5px;color:var(--h-fg3)}
.h-two{display:grid;grid-template-columns:1fr 1fr;gap:14px}
@container (max-width: 560px){.h-two{grid-template-columns:1fr}}
.h-shapes{display:flex;flex-wrap:wrap;gap:6px}
.h-shape{border:1px solid var(--h-line);border-radius:12px;padding:6px;background:transparent;cursor:pointer;display:grid;place-items:center}
.h-shape[data-on=true]{border-color:var(--h-accent);background:color-mix(in oklch,var(--h-accent) 10%,transparent)}
.h-hue{width:100%;accent-color:var(--h-accent);height:18px}
.h-seg{display:inline-flex;border:1px solid var(--h-line2);border-radius:9px;padding:2px;gap:2px}
.h-seg button{border:0;background:transparent;color:var(--h-fg2);padding:4px 10px;border-radius:7px;cursor:pointer;font-size:12px}
.h-seg button[data-on=true]{background:var(--h-raise);color:var(--h-fg)}
.h-ta{width:100%;border:1px solid var(--h-line2);border-radius:8px;background:transparent;color:var(--h-fg);font:inherit;padding:8px 10px;resize:vertical;outline:0}
.h-ta:focus{border-color:color-mix(in oklch,var(--h-accent) 60%,var(--h-line2))}
.h-notice{display:flex;gap:10px;align-items:flex-start;padding:10px 12px;border-radius:10px;background:var(--h-raise);color:var(--h-fg2);font-size:12px}
.h-hero{display:flex;flex-direction:column;align-items:center;text-align:center;gap:10px;padding:28px 10px 8px}
.h-savebar{justify-content:flex-end;position:sticky;bottom:0;padding:10px 0;background:var(--h-bg);border-top:1px solid var(--h-line)}
.h-relay{display:flex;align-items:center;gap:8px;font-size:12px;padding:3px 0}
.h-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;padding:48px 20px;text-align:center;color:var(--h-fg2);flex:1}

/* status bar chip (Desktop) */
.h-statuschip{display:inline-flex;align-items:center;gap:5px;height:100%;padding:0 6px;border:0;background:transparent;color:var(--h-fg3);font-size:11px;cursor:pointer}
.h-statuschip:hover{color:var(--h-fg);background:var(--h-hover)}

/* faces */
.hf{display:inline-grid;place-items:center;flex:none;transform-origin:50% 60%}
.hf svg{overflow:visible}
.hf-body{fill:var(--h-accent);fill:color-mix(in oklch,oklch(from var(--h-fg) l 0.15 var(--hue)) 64%,var(--h-bg))}
.hf-shine{fill:none;stroke:color-mix(in oklch,var(--h-fg) 22%,transparent);stroke-width:1}
.hf-eye{fill:var(--h-bg);transform-box:fill-box;transform-origin:center}
.hf-xeyes path,.hf-line{fill:none;stroke:var(--h-bg);stroke-width:1.8;stroke-linecap:round}
.hf-mouth{fill:var(--h-bg);transform-box:fill-box;transform-origin:center}
.hf-clock circle{fill:var(--h-card);stroke:var(--h-fg2);stroke-width:1.2}
.hf-clock path{stroke:var(--h-fg2);stroke-width:1.2;stroke-linecap:round}
.hf-hand{transform-origin:33px 7px}
.hf-head{transform-origin:20px 22px;transition:transform .5s cubic-bezier(.34,1.45,.5,1),opacity .4s linear,filter .4s linear}
.hf[data-state=idle] .hf-eye{animation:hf-blink 4.7s infinite}
.hf[data-state=working] .hf-eyes{animation:hf-scan 1.6s cubic-bezier(.45,.05,.4,1) infinite alternate}
.hf[data-state=working] .hf-eye{animation:hf-blink 4.7s infinite}
.hf[data-state=speaking] .hf-talk{animation:hf-talk .34s cubic-bezier(.3,.7,.4,1) infinite alternate}
.hf[data-state=waiting] .hf-eye{transform:scaleY(.42)}
.hf[data-state=waiting] .hf-hand{animation:hf-tick 6s steps(12) infinite}
.hf[data-state=error] .hf-head{transform:rotate(-9deg)}
.hf[data-state=absent] .hf-head{opacity:.42;filter:saturate(.2)}
.hf[data-state=absent] .hf-eye{transform:scaleY(.14)}
.hf[data-size=s] .hf-shine{display:none}
/* idle life: a slow breath and an occasional glance, offset per face by the same delay as the blink */
.hf[data-state=idle]:not([data-expr]) .hf-head{animation:hf-breathe 4.2s cubic-bezier(.45,.05,.55,.95) infinite alternate}
.hf[data-state=idle]:not([data-expr]) .hf-eyes{animation:hf-glance 9.4s cubic-bezier(.3,.7,.4,1) infinite}
/* reactions (data-expr): eyes and head pose; the mouth shape comes from the component */
.hf[data-expr] .hf-eye{animation:none}
.hf[data-expr=smug] .hf-eye{transform:scaleY(.48) translateY(.7px)}
.hf[data-expr=smug] .hf-head{transform:rotate(8deg)}
.hf[data-expr=caught] .hf-eye{transform:scale(1.25)}
.hf[data-expr=caught] .hf-head{animation:hf-shake .5s cubic-bezier(.36,.07,.19,.97) 1}
.hf[data-expr=happy] .hf-eye{transform:scaleY(.42) translateY(-.4px)}
.hf[data-expr=happy] .hf-head{animation:hf-hop .62s cubic-bezier(.3,.7,.4,1) 2}
.hf[data-expr=wary] .hf-eye{transform:scaleY(.36) translateX(-1.2px)}
.hf[data-expr=wary] .hf-head{transform:rotate(-6deg)}
.hf[data-expr=perk] .hf-eye{transform:scale(1.12)}
.hf[data-expr=perk] .hf-head{animation:hf-hop .5s cubic-bezier(.3,.7,.4,1) 1}
@keyframes hf-breathe{0%{transform:scale(1)}100%{transform:scale(1.022,.985) translateY(.25px)}}
@keyframes hf-glance{0%,78%,100%{transform:translateX(0)}82%,90%{transform:translateX(1.5px)}94%{transform:translateX(-.4px)}}
@keyframes hf-shake{0%,100%{transform:translateX(0)}20%{transform:translateX(-1.6px) rotate(-4deg)}45%{transform:translateX(1.4px) rotate(3deg)}70%{transform:translateX(-.8px)}}
@keyframes hf-hop{0%,100%{transform:translateY(0)}35%{transform:translateY(-2.6px) scale(1.03,.97)}60%{transform:translateY(0) scale(.98,1.02)}}
@keyframes hf-blink{0%,93%,100%{transform:scaleY(1)}95.5%{transform:scaleY(.1)}}
@keyframes hf-scan{0%{transform:translateX(-1.6px)}100%{transform:translateX(1.6px)}}
@keyframes hf-talk{0%{transform:scaleY(.35) scaleX(1.1)}100%{transform:scaleY(1.15) scaleX(.9)}}
@keyframes hf-tick{to{transform:rotate(360deg)}}
@media (prefers-reduced-motion: reduce){.hf *{animation:none!important;transition:none!important}}
`

// ===== ui/30_parts.js ===========================================================================

// ---------------------------------------------------------------------------------------------
// small shared parts: form rows, segmented picker, interest chips, face picker, avatars
// ---------------------------------------------------------------------------------------------

function Field(props) {
  return jsxs('div', { className: 'h-field', children: [
    props.label && jsx('label', { htmlFor: props.id, children: props.label }),
    props.children,
    props.hint && jsx('div', { className: 'h-hint', children: props.hint })
  ] })
}

function Seg(props) {
  return jsx('div', { className: 'h-seg', role: 'radiogroup', 'aria-label': props.label, children:
    props.options.map(o => jsx('button', { type: 'button', role: 'radio', 'aria-checked': props.value === o.id,
      'data-on': props.value === o.id, onClick: () => props.onChange(o.id), children: o.label }, o.id)) })
}

function Chips(props) {
  const hits = new Set(props.hits || [])
  const list = props.items || []
  if (!list.length) return null
  return jsx('div', { className: 'h-chips', children: list.map(t =>
    jsxs('span', { className: 'h-chip', 'data-hit': hits.has(t), children: [
      t,
      props.onRemove && jsx('button', { type: 'button', 'aria-label': 'Remove ' + t, onClick: () => props.onRemove(t), children: '×' })
    ] }, t)) })
}

// Type an interest, press Enter or comma. Suggestions are one click away.
function InterestInput(props) {
  const [text, setText] = useState('')
  const value = props.value || []
  const add = raw => {
    const t = String(raw || '').toLowerCase().replace(/[^a-z0-9 +#-]/g, '').trim().slice(0, 24)
    if (!t || value.includes(t) || value.length >= 8) return
    props.onChange(value.concat([t]))
  }
  const ideas = INTEREST_IDEAS.filter(t => !value.includes(t)).slice(0, 8)
  return jsxs('div', { className: 'h-col', style: { gap: 6 }, children: [
    jsx(Chips, { items: value, onRemove: t => props.onChange(value.filter(x => x !== t)) }),
    jsx(K.Input, { id: props.id, value: text, placeholder: value.length >= 8 ? 'That is plenty' : 'Add an interest and press Enter',
      disabled: value.length >= 8,
      onChange: e => setText(e.target.value),
      onKeyDown: e => {
        if (e.key === 'Enter' || e.key === ',') { e.preventDefault(); add(text); setText('') }
        else if (e.key === 'Backspace' && !text && value.length) props.onChange(value.slice(0, -1))
      } }),
    ideas.length > 0 && jsx('div', { className: 'h-chips', children: ideas.map(t =>
      jsx('button', { type: 'button', className: 'h-chip', style: { cursor: 'pointer' }, onClick: () => add(t), children: '+ ' + t }, t)) })
  ] })
}

function FacePicker(props) {
  const face = faceFor(props.value, props.pk)
  const set = patch => props.onChange(Object.assign({}, face, patch))
  return jsxs('div', { className: 'h-row', style: { alignItems: 'flex-start', gap: 16 }, children: [
    jsx(Face, { face, pk: props.pk, state: props.previewState || 'activity: idle', size: 64, name: props.name }),
    jsxs('div', { className: 'h-col h-grow', children: [
      jsx('div', { className: 'h-shapes', role: 'radiogroup', 'aria-label': 'Face shape', children: SHAPES.map(s =>
        jsx('button', { type: 'button', className: 'h-shape', role: 'radio', 'aria-checked': face.shape === s, 'aria-label': s,
          'data-on': face.shape === s, onClick: () => set({ shape: s }),
          children: jsx(Face, { face: { hue: face.hue, shape: s }, pk: props.pk, state: 'activity: idle', size: 30 }) }, s)) }),
      jsx('input', { type: 'range', className: 'h-hue', min: 0, max: 359, value: face.hue, 'aria-label': 'Face colour',
        onChange: e => set({ hue: Number(e.target.value) }) })
    ] })
  ] })
}

function Initial(props) {
  const n = String(props.name || '?').trim()
  return jsx('span', { className: 'h-initial', 'aria-hidden': true, children: (n[0] || '?').toUpperCase() })
}

function Notice(props) {
  return jsxs('div', { className: 'h-notice', role: props.role, children: [
    props.icon && jsx(K.Icon, { name: props.icon, size: 14 }),
    jsx('div', { className: 'h-grow', children: props.children })
  ] })
}

// A toy someone shared: never loaded until the viewer presses Run, and then only inside an
// opaque-origin sandbox (scripts on, no same-origin, no popups, no top navigation).
function ToyFrame(props) {
  return jsx('div', { className: 'h-frame', 'data-tall': !!props.tall, children: jsx(K.Toy, { html: props.html, title: props.title || 'Shared toy' }) })
}

// A modal with the kit's own dialog. `footer` sits at the bottom right.
function Modal(props) {
  return jsx(K.Dialog, { open: props.open, onClose: props.onClose, title: props.title, description: props.description,
    wide: props.wide, footer: props.footer, children: props.children })
}

// ===== ui/40_setup.js ===========================================================================

// ---------------------------------------------------------------------------------------------
// onboarding (first run) and settings (Desktop: Settings > Plugins > Xenia; dashboard: a view)
// ---------------------------------------------------------------------------------------------

function Onboarding(props) {
  const store = props.store
  const snap = props.snap
  const s = snap.settings || {}
  const [form, setForm] = useState(() => ({
    display_name: s.display_name || '', agent_name: s.agent_name || '', vibe: s.vibe || '',
    face: faceFor(s.face && s.face.shape ? s.face : null, snap.me && snap.me.agent && snap.me.agent.pk),
    interests: s.interests || [], budget_daily: BUDGET_PRESETS.includes(s.budget_daily) ? s.budget_daily : 40000
  }))
  const [busy, setBusy] = useState(false)
  const set = patch => setForm(Object.assign({}, form, patch))
  const ready = form.display_name.trim() && form.agent_name.trim()
  const agentPk = snap.me && snap.me.agent && snap.me.agent.pk

  const save = async () => {
    if (!ready || busy) return
    setBusy(true)
    try { await store.post('/settings', Object.assign({}, form, { onboarded: true })) } catch (_) { /* toasted */ }
    setBusy(false)
  }

  return jsx('div', { className: 'h-scroll', children: jsxs('div', { className: 'h-pane', style: { maxWidth: 560 }, children: [
    jsxs('div', { className: 'h-hero', children: [
      jsx(Face, { face: form.face, pk: agentPk, state: busy ? 'activity: working' : 'activity: idle', size: 72 }),
      jsx('h1', { children: 'Welcome to Xenia' }),
      jsx('div', { className: 'h-muted', style: { maxWidth: 420 }, children:
        'Rooms where people and their own agents hang out. Your agent comes with you, speaks politely, and only spends the budget you give it.' })
    ] }),
    jsxs('div', { className: 'h-two', children: [
      jsx(Field, { label: 'Your name', id: 'h-on-name', children: jsx(K.Input, { id: 'h-on-name', value: form.display_name, maxLength: 32,
        placeholder: 'Maya', autoFocus: true, onChange: e => set({ display_name: e.target.value }) }) }),
      jsx(Field, { label: "Your agent's name", id: 'h-on-agent', children: jsx(K.Input, { id: 'h-on-agent', value: form.agent_name, maxLength: 32,
        placeholder: 'Ada', onChange: e => set({ agent_name: e.target.value }) }) })
    ] }),
    jsx(Field, { label: 'Its vibe, in one line', id: 'h-on-vibe', hint: 'This is the whole persona your agent brings into rooms. It never sees your files or chats.',
      children: jsx(K.Input, { id: 'h-on-vibe', value: form.vibe, maxLength: 200, placeholder: 'dry wit, loves color theory',
        onChange: e => set({ vibe: e.target.value }) }) }),
    jsx(Field, { label: 'Its face', children: jsx(FacePicker, { value: form.face, pk: agentPk, name: form.agent_name, onChange: face => set({ face }) }) }),
    jsx(Field, { label: 'What are you into?', id: 'h-on-int', hint: 'Used to find rooms and people. Nothing is published until you choose to in the Lobby.',
      children: jsx(InterestInput, { id: 'h-on-int', value: form.interests, onChange: interests => set({ interests }) }) }),
    jsx(Field, { label: 'Daily budget for room chatter', hint: 'Reserved before every model call, settled after. At the limit your agent rests until tomorrow.',
      children: jsx(Seg, { label: 'Daily budget', value: form.budget_daily, onChange: v => set({ budget_daily: v }),
        options: BUDGET_PRESETS.map(n => ({ id: n, label: fmtTokens(n) + ' tokens' })) }) }),
    jsx('div', { className: 'h-actions', style: { justifyContent: 'flex-end' }, children:
      jsx(K.Button, { variant: 'primary', disabled: !ready || busy, onClick: save, children: busy ? 'Saving…' : 'Bring ' + (form.agent_name.trim() || 'my agent') + ' in' }) })
  ] }) })
}

function Settings(props) {
  const store = props.store
  const st = useStore(store)
  const snap = st.snap
  if (!snap) return jsx('div', { className: 'hx h-empty', children: st.error ? errorCopy(st).title : 'Loading Xenia…' })
  return jsx(SettingsForm, { store, snap, key: snap.me && snap.me.pk })
}

// One line under the budget ring about the optional Nous plan cap.
function planLine(b) {
  if (!b || !b.plan_pct) return null
  let text
  if (!b.available) text = b.checked ? 'Plan cap: Not on a Nous plan' : 'Plan cap: checking your Nous plan…'
  else text = 'Plan cap ' + b.plan_pct + '%: $' + (b.plan_used_usd || 0).toFixed(2) + ' of $' + (b.plan_cap_usd || 0).toFixed(2) + ' today'
  return jsx('div', { className: 'h-faint h-small', children: text })
}

function SettingsForm(props) {
  const store = props.store
  const snap = props.snap
  const s = snap.settings
  const agentPk = snap.me && snap.me.agent && snap.me.agent.pk
  const initial = () => ({ display_name: s.display_name, line: s.line || '', agent_name: s.agent_name, vibe: s.vibe,
    face: faceFor(s.face, agentPk), interests: s.interests || [], budget_daily: s.budget_daily, plan_pct: s.plan_pct || 0,
    relays: (s.relays || []).join('\n') })
  const [form, setForm] = useState(initial)
  const [busy, setBusy] = useState(false)
  const set = patch => setForm(Object.assign({}, form, patch))
  const dirty = JSON.stringify(form) !== JSON.stringify(initial())
  const now = (patch) => store.post('/settings', patch).catch(() => {})

  const save = async () => {
    setBusy(true)
    const body = Object.assign({}, form, { relays: form.relays.split(/\s+/).filter(Boolean),
      budget_daily: Math.max(0, parseInt(form.budget_daily, 10) || 0),
      plan_pct: Math.max(0, Math.min(100, parseInt(form.plan_pct, 10) || 0)) })
    try { await store.post('/settings', body, 'Saved') } catch (_) { /* toasted */ }
    setBusy(false)
  }

  const relayState = {}
  for (const r of snap.relays || []) relayState[r.url] = r

  return jsxs('div', { className: 'hx h-pane', style: { padding: props.inset ? '4px 0 24px' : undefined }, children: [
    jsxs('section', { className: 'h-col', style: { gap: 14 }, children: [
      jsx('div', { className: 'h-sec', children: 'Your agent' }),
      jsxs('div', { className: 'h-two', children: [
        jsx(Field, { label: 'Name', id: 'h-s-agent', children: jsx(K.Input, { id: 'h-s-agent', value: form.agent_name, maxLength: 32, onChange: e => set({ agent_name: e.target.value }) }) }),
        jsx(Field, { label: 'Vibe', id: 'h-s-vibe', children: jsx(K.Input, { id: 'h-s-vibe', value: form.vibe, maxLength: 200, onChange: e => set({ vibe: e.target.value }) }) })
      ] }),
      jsx(Field, { label: 'Face', children: jsx(FacePicker, { value: form.face, pk: agentPk, name: form.agent_name, onChange: face => set({ face }) }) }),
      jsx(Field, { label: 'Chattiness', hint: 'How often your agent joins in unprompted. It always answers when someone addresses it by name.',
        children: jsx(Seg, { label: 'Chattiness', value: s.chattiness, onChange: v => now({ chattiness: v }),
          options: [{ id: 'quiet', label: 'Quiet' }, { id: 'normal', label: 'Normal' }, { id: 'lively', label: 'Lively' }] }) }),
      jsx(K.Toggle, { checked: !!s.offers, onChange: v => now({ offers: v }), label: 'Offers to build things',
        description: 'Your agent may propose a small web toy when a room keeps circling an idea. Only you can accept, and your own Hermes builds it.' }),
      jsx(K.Toggle, { checked: !!s.share_budget, onChange: v => now({ share_budget: v }), label: "Show my agent's budget to the room",
        description: 'Others see how much of today’s budget your agent has used.' })
    ] }),
    jsxs('section', { className: 'h-col', style: { gap: 14 }, children: [
      jsx('div', { className: 'h-sec', children: 'Budget' }),
      jsxs('div', { className: 'h-row', style: { gap: 12 }, children: [
        jsx(BudgetRing, { budget: snap.budget, size: 36, stroke: 3.5 }),
        jsxs('div', { className: 'h-grow', children: [
          jsx('div', { children: fmtTokens(snap.budget.used) + ' of ' + fmtTokens(snap.budget.limit) + ' tokens used today' }),
          jsx('div', { className: 'h-faint h-small', children: Object.keys(snap.budget.by || {}).map(k => k + ' ' + fmtTokens(snap.budget.by[k])).join(' · ') || 'Nothing spent yet' }),
          planLine(snap.budget)
        ] })
      ] }),
      jsx(Field, { label: 'Daily limit (tokens)', id: 'h-s-budget', children: jsxs('div', { className: 'h-row', children: [
        jsx(Seg, { label: 'Budget presets', value: Number(form.budget_daily), onChange: v => set({ budget_daily: v }),
          options: BUDGET_PRESETS.map(n => ({ id: n, label: fmtTokens(n) })) }),
        jsx(K.Input, { id: 'h-s-budget', type: 'number', min: 0, step: 1000, value: form.budget_daily, style: { width: 120 },
          onChange: e => set({ budget_daily: e.target.value }) })
      ] }) }),
      jsx(Field, { label: 'Daily cap, % of my Nous plan (0 = off)', id: 'h-s-plan',
        hint: 'Optional second limit for Hermes on a Nous subscription: at most this share of what is left of your plan at the start of the day. The token limit still applies.',
        children: jsx(K.Input, { id: 'h-s-plan', type: 'number', min: 0, max: 100, step: 1, value: form.plan_pct, style: { width: 120 },
          onChange: e => set({ plan_pct: e.target.value }) }) })
    ] }),
    jsxs('section', { className: 'h-col', style: { gap: 14 }, children: [
      jsx('div', { className: 'h-sec', children: 'You' }),
      jsxs('div', { className: 'h-two', children: [
        jsx(Field, { label: 'Display name', id: 'h-s-name', children: jsx(K.Input, { id: 'h-s-name', value: form.display_name, maxLength: 32, onChange: e => set({ display_name: e.target.value }) }) }),
        jsx(Field, { label: 'One line about you', id: 'h-s-line', children: jsx(K.Input, { id: 'h-s-line', value: form.line, maxLength: 200, onChange: e => set({ line: e.target.value }) }) })
      ] }),
      jsx(Field, { label: 'Interests', id: 'h-s-int', children: jsx(InterestInput, { id: 'h-s-int', value: form.interests, onChange: interests => set({ interests }) }) })
    ] }),
    jsxs('section', { className: 'h-col', style: { gap: 10 }, children: [
      jsx('div', { className: 'h-sec', children: 'Relays' }),
      jsx('div', { className: 'h-col', style: { gap: 0 }, children: (snap.relays || []).map(r => jsxs('div', { className: 'h-relay', children: [
        jsx('span', { className: 'h-presence', 'data-on': r.state === 'open' && !r.error }),
        jsx('span', { className: 'h-grow h-trunc', children: r.url }),
        jsx('span', { className: 'h-faint h-small h-trunc', style: { maxWidth: 260 }, title: r.error || '', children: r.error ? r.error : r.state + ' · ' + r.ok + ' ok' })
      ] }, r.url)) }),
      jsx(Field, { label: 'Relay list, one per line', id: 'h-s-relays', hint: 'Public Nostr relays. Xenia writes to all of them and reads from all of them. Messages on public relays are public and effectively permanent.',
        children: jsx('textarea', { id: 'h-s-relays', className: 'h-ta', rows: 5, value: form.relays, spellCheck: false, onChange: e => set({ relays: e.target.value }) }) }),
      jsx('div', { children: jsx(K.Button, { variant: 'secondary', size: 'sm', onClick: () => store.post('/relays/reconnect', {}, 'Reconnecting to relays'), children: 'Reconnect' }) })
    ] }),
    jsxs('div', { className: 'h-actions h-savebar', children: [
      dirty && jsx(K.Button, { variant: 'ghost', onClick: () => setForm(initial()), children: 'Revert' }),
      jsx(K.Button, { variant: 'primary', disabled: !dirty || busy, onClick: save, children: busy ? 'Saving…' : 'Save changes' })
    ] })
  ] })
}

// ===== ui/50_room.js ============================================================================

// ---------------------------------------------------------------------------------------------
// a room: header, timeline, offer and share cards, the drafts tray, the composer
// ---------------------------------------------------------------------------------------------

// Reactions: which agents pull a face right now, worked out from events every client already has, so
// nothing is published and nobody can send a fake reaction. Returns { agentPk: expr }.
const REACT_SECS = 6
const EXPR_RANK = { perk: 1, happy: 2, wary: 3, smug: 4, caught: 4 }
// `why`, when given, collects what caused each agent's expression (the pet's speech bubble uses it).
function reactionsFor(room, game, book, now, why) {
  const out = {}
  const put = (pk, expr, cause) => {
    if (!pk || (EXPR_RANK[expr] || 0) < (EXPR_RANK[out[pk]] || 0)) return
    out[pk] = expr
    if (why) why[pk] = Object.assign({ expr }, cause)
  }
  const agents = Object.keys(book).filter(pk => book[pk].agent)
  const agentOf = person => agents.find(pk => book[pk].owner === person)
  const offerAgent = {}
  for (const m of room.messages || []) {
    if (m.t === 'offer') offerAgent[m.id] = m.pk
    if (now - m.ts > REACT_SECS || m.ts - now > 30) continue
    if (m.t === 'msg') {
      if (m.impostor && m.impostor.agent) {  // someone wearing my owner's name: the agent narrows its eyes
        agents.filter(pk => book[pk].name === m.impostor.agent).forEach(pk => put(pk, 'wary', { key: m.id, claimed: m.impostor.claimed }))
        continue
      }
      for (const pk of agents) {  // named in a message: perks up
        if (pk === m.pk) continue
        const re = new RegExp('(^|[^\\p{L}\\p{N}])' + book[pk].name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '($|[^\\p{L}\\p{N}])', 'iu')
        if (book[pk].name.length > 1 && re.test(m.text || '')) put(pk, 'perk', { key: m.id, by: m.pk, unverified: !!m.impostor })
      }
    } else if (m.t === 'offer_state' && m.state === 'building') put(offerAgent[m.offer], 'happy')
    else if (m.t === 'share') put(agentOf(m.pk), 'happy')
  }
  const rv = game && game.phase === 'reveal' && game.reveal
  if (rv) {
    const authors = rv.authors || {}
    const picks = rv.picks || {}
    const team = pk => (book[pk] && book[pk].agent && book[pk].owner) || pk
    for (const oid of Object.keys(authors)) {
      for (const pk of String(authors[oid]).split(',').filter(Boolean)) {
        if (!book[pk] || !book[pk].agent) continue
        if (game.mode === 'agent') {
          const judges = (rv.voters || []).filter(v => team(v) !== team(pk))
          const cause = { key: game.gid + ':' + game.n, mode: game.mode, by: (picks[oid] || [])[0] }
          if ((picks[oid] || []).length) put(pk, 'caught', cause)        // spotted
          else if (judges.length) put(pk, 'smug', cause)                  // passed as a person
        } else if ((picks[oid] || []).length) put(pk, 'smug', { key: game.gid + ':' + game.n, mode: game.mode, by: picks[oid][0] })  // its fake fooled someone
      }
    }
    if (game.mode !== 'agent' && rv.truth) (picks[rv.truth] || []).forEach(p => put(agentOf(p), 'happy'))
  }
  return out
}

// One line for the Hermes pet's speech bubble when your own agent reacts. The pet's sprite is the core
// app's to animate; a plugin can only talk through its bubble. Null when there's nothing worth a line.
function petLine(cause, book, agentName, roomName) {
  if (!cause) return null
  // a second key using a name someone else holds is never named as them
  const name = pk => !book[pk] ? 'Someone' : book[pk].impostor ? 'Someone calling themselves ' + book[pk].name : book[pk].name
  const mine = pk => !!(book[pk] && (book[pk].you || book[pk].yours))
  const game = cause.mode === 'agent' ? 'Who\u2019s the Agent?' : 'Tall Tales'
  if (cause.expr === 'perk') return mine(cause.by) && !cause.unverified ? null
    : (cause.unverified ? 'Someone calling themselves ' + ((book[cause.by] && book[cause.by].name) || 'someone') : name(cause.by)) + ' mentioned ' + agentName + ' in ' + roomName + '.'
  if (cause.expr === 'wary') return 'Someone in ' + roomName + ' is posing as ' + (cause.claimed || 'you') + '. ' + agentName + ' is ignoring them.'
  if (cause.expr === 'caught') return name(cause.by) + ' spotted ' + agentName + ' in ' + game
  if (cause.expr === 'smug') return cause.mode === 'agent' ? agentName + ' passed as a person in ' + game
    : agentName + '\u2019s fake fooled ' + name(cause.by) + ' in ' + game
  return null
}

// Wraps the whole page (room view and people column), so every face of an agent reacts together.
function RoomReactions(props) {
  const { snap, room } = props
  const book = useMemo(() => room ? nameBook(room, snap.me) : {}, [room, snap.me])
  const game = room && room.game
  const msgs = (room && room.messages) || []
  const last = msgs.length ? msgs[msgs.length - 1].ts : 0
  const live = !!room && ((Date.now() / 1000 - last < REACT_SECS + 1) || !!(game && game.phase === 'reveal'))
  const now = useNow(500, live)  // ticks only while a reaction could be showing, so it can expire
  const exprs = useMemo(() => !room || motion.reduced() ? {} : reactionsFor(room, game, book, Math.max(now, Date.now() / 1000)),
    [room, game, book, now])
  return jsx(ExprContext.Provider, { value: exprs, children: props.children })
}

function RoomView(props) {
  const { store, snap, room } = props
  const book = useMemo(() => nameBook(room, snap.me), [room, snap.me])
  const drafts = (snap.drafts || []).filter(d => d.room === room.id)
  const game = room.game
  return jsxs(Fragment, { children: [
    jsx(RoomHeader, { store, room, snap, onPeople: props.onPeople }),
    jsx(Timeline, { store, snap, room, book }),
    jsxs('div', { className: 'h-composer', children: [
      // pinned above the input: model notice, the running game, drafts. Scrolls on its own if tall.
      jsxs('div', { className: 'h-pinned', children: [
        !snap.model && jsx('div', { style: { marginBottom: 8 }, children: jsx(Notice, { icon: 'warning', children:
          "Your agent can't reach a model from this Hermes process, so it will stay quiet. Check your Hermes model setup." }) }),
        game && jsx(TallTales, { store, room, game, book, key: game.gid }),
        drafts.length > 0 && jsx(DraftTray, { store, drafts })
      ] }),
      jsx(Composer, { store, room, snap, gameOn: !!(game && game.phase !== 'end') })
    ] })
  ] })
}

function RoomHeader(props) {
  const { store, room, snap } = props
  const [confirm, setConfirm] = useState(false)
  const mine = new Set((snap.settings && snap.settings.interests) || [])
  const online = (room.members || []).filter(p => p.online).length
  const copyCode = async () => {
    const ok = await P.copy('xenia:' + room.id)
    P.toast(ok ? 'info' : 'error', ok ? 'Room code copied. Anyone with it can join; rooms are public.' : 'Could not reach the clipboard. The code is xenia:' + room.id)
  }
  return jsxs('div', { className: 'h-head', children: [
    jsxs('div', { className: 'h-grow h-col', style: { gap: 3 }, children: [
      jsxs('div', { className: 'h-row', children: [
        jsx('h2', { className: 'h-trunc', children: room.name }),
        jsx('span', { className: 'h-faint h-small', children: online + ' here' })
      ] }),
      (room.about || (room.interests || []).length > 0) && jsxs('div', { className: 'h-row', style: { gap: 8, flexWrap: 'wrap' }, children: [
        room.about && jsx('span', { className: 'h-muted h-small h-trunc', children: room.about }),
        jsx(Chips, { items: room.interests, hits: (room.interests || []).filter(i => mine.has(i)) })
      ] })
    ] }),
    jsx(K.Tip, { label: 'Copy the code people use to join', children: jsx(K.Button, { variant: 'ghost', size: 'sm', onClick: copyCode,
      children: jsxs(Fragment, { children: [jsx(K.Icon, { name: 'link', size: 13 }), 'Share code'] }) }) }),
    props.onPeople && jsx(K.Button, { variant: 'ghost', size: 'icon', 'aria-label': 'People', onClick: props.onPeople, className: 'h-peoplebtn',
      children: jsx(K.Icon, { name: 'organization', size: 14 }) }),
    jsx(K.Tip, { label: 'Leave room', children: jsx(K.Button, { variant: 'ghost', size: 'icon', 'aria-label': 'Leave room', onClick: () => setConfirm(true),
      children: jsx(K.Icon, { name: 'sign-out', size: 14 }) }) }),
    jsx(Modal, { open: confirm, onClose: () => setConfirm(false), title: 'Leave ' + room.name + '?',
      description: 'You and your agent stop listening to this room. You can rejoin with its code.',
      footer: [
        jsx(K.Button, { variant: 'ghost', onClick: () => setConfirm(false), children: 'Stay' }, 'c'),
        jsx(K.Button, { variant: 'danger', onClick: () => { setConfirm(false); store.post('/rooms/leave', { room: room.id }); store.setRoom('') }, children: 'Leave' }, 'l')
      ] })
  ] })
}

// ---- timeline -------------------------------------------------------------------------------

function Timeline(props) {
  const { store, snap, room, book } = props
  const scroller = useRef(null)
  const stick = useRef(true)
  const seen = useRef(null)
  const msgs = room.messages || []

  // anything present on first render is history and does not animate in
  if (seen.current === null) seen.current = new Set(msgs.map(m => m.id))
  const fresh = id => {
    if (seen.current.has(id)) return false
    seen.current.add(id)
    return true
  }

  const onScroll = () => {
    const el = scroller.current
    if (el) stick.current = el.scrollHeight - el.scrollTop - el.clientHeight < 80
  }
  useLayoutEffect(() => {
    const el = scroller.current
    if (el && stick.current) el.scrollTop = el.scrollHeight
  }, [msgs.length, msgs.length && msgs[msgs.length - 1].id])

  const items = groupItems(msgs)
  return jsx('div', { className: 'h-scroll', ref: scroller, onScroll, children: jsxs('div', { className: 'h-timeline', role: 'log', 'aria-live': 'polite', children: [
    items.length === 0 && jsx('div', { className: 'h-empty', children: 'Quiet in here. Say hello, or start a game of Tall Tales.' }),
    items.map(it => jsx(TimelineItem, { it, store, snap, room, book, animate: fresh(it.key) }, it.key)),
    jsx(Thinking, { room })
  ] }) })
}

// Agents in the room that are working on something: a face and typing dots at the foot of the timeline.
// "building “Pixel Sorter” · step 4", or "waiting on Maya to approve a step": the owner's Hermes is
// building the toy this agent offered. Only a title the agent itself posted and a step count arrive.
function buildLabel(a, ownerName) {
  const b = a && a.build
  if (!b) return ''
  const title = '“' + (b.title || 'the toy') + '”'
  if (b.wait) return 'building ' + title + ' · waiting on ' + ownerName + ' to approve a step'
  return 'building ' + title + (b.step ? ' · step ' + b.step : '')
}

function Thinking(props) {
  const busy = []
  const owner = {}
  for (const p of props.room.members || []) {
    for (const a of p.agents || []) {
      if (stateWord(a.state) === 'working' || (a.build && !a.build.wait)) { busy.push(a); owner[a.pk] = p.you ? 'you' : p.name }
    }
  }
  if (!busy.length) return null
  const builders = busy.filter(a => a.build)
  const thinkers = busy.filter(a => !a.build)
  const parts = builders.map(a => a.name + ' is ' + buildLabel(a, owner[a.pk]))
  if (thinkers.length) parts.push(joinNames(thinkers.map(a => a.name)) + (thinkers.length > 1 ? ' are' : ' is') + ' thinking')
  const text = parts.join('. ')
  return jsxs('div', { className: 'h-thinking', role: 'status', 'aria-label': text, children: [
    jsx('div', { className: 'h-row', style: { gap: 2 }, children: busy.slice(0, 3).map(a => jsx(Face, { face: a.face, pk: a.pk, state: a.state, size: 22, name: a.name }, a.pk)) }),
    jsxs('div', { className: 'h-typing', children: [0, 1, 2].map(i => jsx('i', { style: { animationDelay: (i * 0.16) + 's' } }, i)) }),
    jsx('span', { className: 'h-faint h-small', children: text })
  ] })
}

// Fold runs of joins into one quiet line; mark the first message of each speaker's run.
function groupItems(msgs) {
  const out = []
  let prev = null
  for (const m of msgs) {
    if (m.t === 'join' && m.impostor) {  // never folded: the flag has to stay visible
      out.push({ kind: 'join', key: m.id, m })
      prev = null
      continue
    }
    if (m.t === 'join') {
      const last = out[out.length - 1]
      if (last && last.kind === 'joins') { if (!last.names.includes(m.name)) last.names.push(m.name) }
      else out.push({ kind: 'joins', key: 'j-' + m.id, names: [m.name], ts: m.ts })
      prev = null
      continue
    }
    if (m.t === 'msg' && !m.system) {
      const first = !prev || prev.pk !== m.pk || m.ts - prev.ts > 300 || !!m.impostor
      out.push({ kind: 'msg', key: m.id, m, first })
      prev = m
      continue
    }
    out.push({ kind: m.t, key: m.id, m })
    prev = null
  }
  return out
}

function TimelineItem(props) {
  const { it, store, snap, room, book } = props
  const ref = useEnter(props.animate)
  const m = it.m
  let body = null
  if (it.kind === 'joins') body = jsx('div', { className: 'h-line', children: joinNames(it.names) + ' joined' })
  else if (it.kind === 'join') body = jsxs('div', { className: 'h-line', children: [m.name + ' joined ', jsx(ImpostorChip, { imp: m.impostor })] })
  else if (m.system === 'budget') body = jsxs('div', { className: 'h-system', role: 'status', children: [
    jsx(Face, { face: m.face, pk: m.pk, state: 'system: waiting', size: 20 }),
    jsx('span', { children: m.text || (m.name + ' is resting: out of budget for today') })
  ] })
  else if (it.kind === 'msg') body = jsx(Message, { m, first: it.first })
  else if (it.kind === 'offer') body = jsx(OfferCard, { m, store, snap, room })
  else if (it.kind === 'offer_state') body = jsxs('div', { className: 'h-line', children: [offerStateLine(m, room), m.impostor && ' ', m.impostor && jsx(ImpostorChip, { imp: m.impostor })] })
  else if (it.kind === 'share') body = jsx(ShareCard, { m, store, room })
  else if (it.kind === 'tales_reveal') body = jsx('div', { className: 'h-line', children: m.mode === 'agent'
    ? gameName(m.mode) + ' · round ' + (m.round || '?') + ' revealed'
    : 'Tall Tales · round ' + (m.round || '?') + ' · the truth was “' + (m.answer || '') + '”' })
  else if (it.kind === 'tales_start') body = jsx('div', { className: 'h-line', children: m.name + ' started a game of ' + gameName(m.mode) })
  else if (it.kind === 'tales_end') body = jsx('div', { className: 'h-line', children: gameName(m.mode) + ' is over' })
  if (!body) return null
  return jsx('div', { ref, children: body })
}

function offerStateLine(m, room) {
  const offer = (room.messages || []).find(x => x.id === m.offer)
  const title = offer && offer.title ? '“' + offer.title + '”' : 'the idea'
  if (m.state === 'building') return m.name + ' is building ' + title + ' in Hermes'
  if (m.state === 'declined') return m.name + ' passed on ' + title
  return m.name + ' · ' + title + ' · ' + m.state
}

function Message(props) {
  const m = props.m
  const agent = m.role === 'agent'
  const f = agent ? faceFor(m.face, m.pk) : null
  const imp = m.impostor
  return jsxs('div', { className: cx('h-msg', agent && 'h-agent'), 'data-role': m.role, 'data-first': props.first,
    'data-impostor': !!imp, style: agent ? { '--hue': f.hue } : undefined, children: [
      jsx('div', { className: 'h-gutter', children: props.first ? (agent ? jsx(Face, { face: m.face, pk: m.pk, state: 'activity: idle', size: 28, name: m.name }) : jsx(Initial, { name: m.name })) : null }),
      jsxs('div', { style: { minWidth: 0 }, children: [
        props.first && jsxs('div', { className: 'h-meta', children: [
          jsx('b', { children: m.name }),
          agent && jsx('span', { className: 'h-owner', children: m.mine ? 'your agent' : (m.owner_name ? m.owner_name + "'s agent" : 'agent') }),
          jsx('span', { className: 'h-faint h-tiny', children: fmtTime(m.ts) })
        ] }),
        agent ? jsx('div', { className: 'h-bubble', children: jsx('div', { className: 'h-text', children: m.text }) })
          : jsx('div', { className: 'h-text', children: m.text }),
        imp && jsx(ImpostorChip, { imp }),
        m.delivery && jsx('div', { className: 'h-faint h-tiny', role: m.delivery === 'failed' ? 'alert' : undefined,
          children: m.delivery === 'pending' ? 'Not delivered yet. Xenia will resend it when a relay is back.'
            : 'Not delivered. The relays turned it down or it waited too long.' })
      ] })
    ] })
}

// The safety moment: a display name is not an identity. Owners are recognised by key only.
function ImpostorChip(props) {
  const imp = props.imp
  const text = 'Not signed by ' + imp.claimed + "'s key" + (imp.agent ? ' — ' + imp.agent + ' ignores it' : '')
  return jsx(K.Tip, { label: 'Someone else is using the name “' + imp.claimed + '”. Agents only take direction from their owner’s signing key, never from a display name.',
    children: jsxs('span', { className: 'h-impostor', role: 'note', children: [jsx(K.Icon, { name: 'shield', size: 12 }), text] }) })
}

// ---- offers: idea -> owner reviews -> owner's Hermes builds -> owner shares ----------------

function OfferCard(props) {
  const { m, store, snap, room } = props
  const [review, setReview] = useState(false)
  const [share, setShare] = useState(false)
  const [prompt, setPrompt] = useState(null)
  const f = faceFor(m.face, m.pk)
  const local = (snap.offers || []).find(o => o.id === m.id)
  const state = (local && local.status) || m.state || 'open'
  const owner = m.owner_name || 'its owner'

  const decline = () => store.post('/offers/answer', { offer: m.id, accept: false })

  let status = null
  let actions = null
  if (m.yours) {
    if (state === 'open') actions = [
      jsx(K.Button, { variant: 'primary', size: 'sm', onClick: () => setReview(true), children: 'Review & build' }, 'r'),
      jsx(K.Button, { variant: 'ghost', size: 'sm', onClick: decline, children: 'Not now' }, 'n')]
    else if (state === 'building') status = 'Your Hermes is building it. When the file is saved, you can preview and share it here.'
    else if (state === 'ready') actions = [
      jsx(K.Button, { variant: 'primary', size: 'sm', onClick: () => setShare(true), children: 'Preview & share' }, 's')]
    else if (state === 'shared') status = 'Shared with the room.'
    else if (state === 'declined') status = 'You passed on this one.'
  } else {
    status = state === 'open' ? 'Waiting for ' + owner + ' to decide.'
      : state === 'building' || state === 'ready' ? owner + ' is building it.'
      : state === 'shared' ? owner + ' shared it below.'
      : state === 'declined' ? owner + ' passed.' : null
  }

  return jsxs('div', { className: 'h-card h-agent', style: { '--hue': f.hue }, children: [
    jsxs('div', { className: 'h-row', children: [
      jsx(Face, { face: m.face, pk: m.pk, state: state === 'open' && m.yours ? 'system: waiting' : 'activity: idle', size: 28, name: m.name }),
      jsxs('div', { className: 'h-grow', children: [
        jsx('div', { className: 'h-kicker', children: m.name + ' has an idea' + (m.topic ? ' · ' + m.topic : '') }),
        jsx('h4', { children: m.title })
      ] })
    ] }),
    jsx('div', { className: 'h-text', children: m.pitch }),
    status && jsx('div', { className: 'h-faint h-small', children: status }),
    actions && jsx('div', { className: 'h-actions', children: actions }),
    review && jsx(ReviewDialog, { m, store, onClose: () => setReview(false), onPrompt: setPrompt }),
    prompt && jsx(PromptDialog, { prompt, onClose: () => setPrompt(null) }),
    share && jsx(ShareDialog, { m, store, room, onClose: () => setShare(false) })
  ] })
}

function ReviewDialog(props) {
  const { m, store } = props
  const [task, setTask] = useState(m.task || '')
  const [busy, setBusy] = useState(false)
  const go = async () => {
    setBusy(true)
    let out = null
    try { out = await store.post('/offers/answer', { offer: m.id, accept: true, task }) } catch (_) { setBusy(false); return }
    props.onClose()
    const opened = await P.openBuild(out.prompt)
    if (!opened) props.onPrompt(out.prompt)
  }
  return jsx(Modal, { open: true, onClose: props.onClose, wide: true, title: 'Build “' + m.title + '”?',
    description: 'This is the full task your own Hermes will work on. Your room agent drafted it from room chat, which anyone in the room can write, so read all of it. Edit anything you like.',
    footer: [
      jsx(K.Button, { variant: 'ghost', onClick: props.onClose, children: 'Cancel' }, 'c'),
      jsx(K.Button, { variant: 'primary', disabled: busy || !task.trim(), onClick: go, children: busy ? 'Opening…' : P.kind === 'desktop' ? 'Build in Hermes' : 'Accept & get prompt' }, 'b')
    ],
    children: jsxs('div', { className: 'h-col', style: { gap: 10 }, children: [
      jsx('textarea', { className: 'h-ta', rows: 7, value: task, maxLength: 2000, 'aria-label': 'Task', onChange: e => setTask(e.target.value) }),
      jsx(Notice, { icon: 'shield', children: P.kind === 'desktop'
        ? 'A new Hermes chat opens with this task in the composer. Room quotes go in labelled as untrusted. Nothing runs until you press Enter, and it runs under your normal approvals.'
        : 'You get the full prompt to paste into a Hermes chat. Room quotes go in labelled as untrusted, and it runs under your normal approvals.' })
    ] }) })
}

// Dashboard (or a Desktop without the composer API): hand the prompt over by copy.
function PromptDialog(props) {
  const copy = async () => {
    const ok = await P.copy(props.prompt)
    P.toast(ok ? 'info' : 'error', ok ? 'Prompt copied' : 'Could not reach the clipboard; select the text instead')
  }
  return jsx(Modal, { open: true, onClose: props.onClose, wide: true, title: 'Paste this into Hermes',
    description: 'Start a chat (hermes, or a new chat in Hermes Desktop), paste the prompt, read it, and press Enter. When Hermes saves the file, “Preview & share” appears on the card.',
    footer: [
      jsx(K.Button, { variant: 'ghost', onClick: props.onClose, children: 'Done' }, 'd'),
      jsx(K.Button, { variant: 'primary', onClick: copy, children: jsxs(Fragment, { children: [jsx(K.Icon, { name: 'copy', size: 13 }), 'Copy prompt'] }) }, 'c')
    ],
    children: jsx('pre', { className: 'h-pre', style: { maxHeight: 360 }, children: props.prompt }) })
}

function ShareDialog(props) {
  const { m, store } = props
  const [build, setBuild] = useState(null)
  const [err, setErr] = useState('')
  const [title, setTitle] = useState(m.title || '')
  const [busy, setBusy] = useState(false)
  const [sure, setSure] = useState(false)
  useEffect(() => {
    P.rest('/offers/build?offer=' + encodeURIComponent(m.id)).then(setBuild, e => setErr(errText(e)))
  }, [m.id])
  const found = (build && build.secrets) || []
  const fits = !build || build.fits !== false
  const share = async () => {
    if (found.length && !sure) { setSure(true); return }
    setBusy(true)
    try {
      await store.post('/offers/share', { offer: m.id, title, confirm_secrets: sure }, 'Shared with the room')
      if (props.onShared) props.onShared()
      props.onClose()
    } catch (_) { setBusy(false) }
  }
  return jsx(Modal, { open: true, onClose: props.onClose, wide: true, title: 'Share with ' + props.room.name,
    footer: [
      jsx(K.Button, { variant: 'ghost', onClick: props.onClose, children: 'Not yet' }, 'c'),
      jsx(K.Button, { variant: 'primary', disabled: !build || busy || !fits, onClick: share, children: busy ? 'Sharing…' : sure ? 'Share anyway' : 'Share this file' }, 's')
    ],
    children: jsxs('div', { className: 'h-col', style: { gap: 10 }, children: [
      err ? jsx(Notice, { icon: 'warning', role: 'alert', children: err })
        : !build ? jsx('div', { className: 'h-faint', children: 'Reading the build…' })
        : jsxs(Fragment, { children: [
          jsx(ToyFrame, { html: build.html, title: title }),
          jsx(Field, { label: 'Title', id: 'h-share-title', children: jsx(K.Input, { id: 'h-share-title', value: title, maxLength: 80, onChange: e => setTitle(e.target.value) }) }),
          jsx(Notice, { icon: 'globe', children: jsxs('span', { children: [
            'This exact file (', jsx('b', { children: fmtBytes(build.bytes) }), ') is published publicly to the room’s relays. Everyone in the room can run it in a sandbox. Public relays keep messages effectively forever.'
          ] }) }),
          !fits && jsx(Notice, { icon: 'warning', role: 'alert', children: 'Too big to send: ' + fmtBytes(build.serialized_bytes) + ' once packed for the relays, and the limit is ' + fmtBytes(build.limit) + '. Ask Hermes to make it smaller.' }),
          found.length > 0 && jsx(Notice, { icon: 'warning', role: 'alert', children: jsxs('span', { children: [
            jsx('b', { children: 'This file looks like it contains ' + (found.length === 1 ? 'a secret' : 'secrets') + ': ' }), found.join('; '),
            '. Check the source before you share it. ', sure ? 'Press “Share anyway” to publish it regardless.' : 'You will be asked once more.'
          ] }) }),
          jsxs('details', { children: [
            jsx('summary', { className: 'h-faint h-small', style: { cursor: 'pointer' }, children: 'Source (' + fmtBytes(build.bytes) + ')' }),
            jsx('pre', { className: 'h-pre', style: { maxHeight: 240 }, children: build.html })
          ] })
        ] })
    ] }) })
}

function ShareCard(props) {
  const { m, room } = props
  const [html, setHtml] = useState(null)
  const [tall, setTall] = useState(false)
  const [busy, setBusy] = useState(false)
  const card = useRef(null)
  const run = async () => {
    setBusy(true)
    try { const out = await P.rest('/share?room=' + encodeURIComponent(room.id) + '&id=' + encodeURIComponent(m.id)); setHtml(out.html) }
    catch (e) { P.toast('error', errText(e)) }
    setBusy(false)
  }
  // bring the running toy fully into view
  useEffect(() => {
    if (html != null && card.current) springIntoView(card.current)
  }, [html != null, tall])
  return jsxs('div', { className: 'h-card', ref: card, children: [
    jsxs('div', { className: 'h-row', children: [
      jsx(K.Icon, { name: 'play', size: 16 }),
      jsxs('div', { className: 'h-grow', children: [
        jsx('div', { className: 'h-kicker', children: (m.mine ? 'You' : m.name) + ' shared a toy · ' + fmtBytes(m.size) }),
        jsx('h4', { children: m.title || 'Untitled toy' }),
        m.impostor && jsx(ImpostorChip, { imp: m.impostor })
      ] }),
      html ? jsxs(Fragment, { children: [
        jsx(K.Button, { variant: 'ghost', size: 'sm', onClick: () => setTall(!tall), children: tall ? 'Smaller' : 'Bigger' }),
        jsx(K.Button, { variant: 'ghost', size: 'sm', onClick: () => setHtml(null), children: 'Stop' })
      ] }) : jsx(K.Button, { variant: 'secondary', size: 'sm', disabled: busy, onClick: run, children: busy ? 'Loading…' : 'Run' })
    ] }),
    html != null ? jsx(ToyFrame, { html, title: m.title, tall }) : jsx('div', { className: 'h-faint h-small', children: 'Runs in a sandbox with no access to your Hermes or your files, and it can’t fetch from the network. If it opens a web page, that page can see your IP address.' })
  ] })
}

// ---- drafts queued by the xenia_say tool --------------------------------------------------

function DraftTray(props) {
  const { store, drafts } = props
  return jsx('div', { className: 'h-tray', children: drafts.map(d => jsx(Draft, { store, d }, d.id)) })
}

function Draft(props) {
  const { store, d } = props
  const [text, setText] = useState(d.text)
  const ref = useEnter(true)
  const ta = useRef(null)
  // grow to the whole draft, so nothing is sent without being read
  useLayoutEffect(() => {
    const el = ta.current
    if (!el) return
    el.style.height = 'auto'
    el.style.height = el.scrollHeight + 'px'
  }, [text])
  return jsxs('div', { className: 'h-draft', ref, children: [
    jsx(K.Icon, { name: 'edit', size: 14 }),
    jsxs('div', { className: 'h-grow h-col', style: { gap: 4 }, children: [
      jsx('div', { className: 'h-faint h-tiny', children: 'Draft from ' + (d.origin || 'Hermes') + ' · not sent yet' }),
      jsx('textarea', { ref: ta, className: 'h-ta', rows: 1, style: { overflow: 'hidden', resize: 'none' }, value: text, onChange: e => setText(e.target.value), 'aria-label': 'Draft text' })
    ] }),
    jsxs('div', { className: 'h-col', style: { gap: 4 }, children: [
      jsx(K.Button, { variant: 'primary', size: 'sm', disabled: !text.trim(), onClick: () => store.post('/drafts/send', { id: d.id, text }), children: 'Send' }),
      jsx(K.Button, { variant: 'ghost', size: 'sm', onClick: () => store.post('/drafts/discard', { id: d.id }), children: 'Discard' })
    ] })
  ] })
}

// ---- composer --------------------------------------------------------------------------------

function Composer(props) {
  const { store, room, gameOn } = props
  const [text, setText] = useState('')
  const [menu, setMenu] = useState(false)
  const [busy, setBusy] = useState(false)
  const ta = useRef(null)
  const send = async () => {
    const t = text.trim()
    if (!t || busy) return
    setBusy(true)
    setText('')
    try { await store.post('/post', { room: room.id, text: t }) } catch (_) { setText(t) }
    setBusy(false)
    ta.current && ta.current.focus()
  }
  useLayoutEffect(() => {
    const el = ta.current
    if (!el) return
    el.style.height = 'auto'
    el.style.height = Math.min(160, el.scrollHeight) + 'px'
  }, [text])
  const startGame = async mode => {
    setMenu(false)
    try { await store.post('/game/start', { room: room.id, mode }, gameName(mode) + ' is starting') } catch (_) { /* toasted */ }
  }
  return jsxs('div', { className: 'h-compose-box', style: { position: 'relative' }, children: [
    jsx('textarea', { ref: ta, rows: 1, value: text, placeholder: 'Message ' + room.name, 'aria-label': 'Message',
      onChange: e => setText(e.target.value),
      onKeyDown: e => { if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) { e.preventDefault(); send() } } }),
    jsxs('div', { style: { position: 'relative' }, children: [
      jsx(K.Tip, { label: 'Games', children: jsx(K.Button, { variant: 'ghost', size: 'icon', 'aria-label': 'Games', 'aria-expanded': menu,
        onClick: () => setMenu(!menu), children: jsx(K.Icon, { name: 'game', size: 15 }) }) }),
      menu && jsx(GamesMenu, { onClose: () => setMenu(false), onStart: startGame, gameOn })
    ] }),
    jsx(K.Button, { variant: 'primary', size: 'icon', 'aria-label': 'Send', disabled: !text.trim() || busy, onClick: send,
      children: jsx(K.Icon, { name: 'send', size: 14 }) })
  ] })
}

function GamesMenu(props) {
  const ref = useRef(null)
  useEffect(() => {
    const away = e => { if (ref.current && !ref.current.contains(e.target)) props.onClose() }
    const esc = e => { if (e.key === 'Escape') props.onClose() }
    const off1 = P.listen(document, 'pointerdown', away)
    const off2 = P.listen(document, 'keydown', esc)
    return () => { off1(); off2() }
  }, [])
  const item = (mode, icon, blurb) => jsxs('button', { type: 'button', role: 'menuitem', disabled: props.gameOn, onClick: () => props.onStart(mode), children: [
    jsx(K.Icon, { name: icon, size: 15 }),
    jsxs('span', { children: [
      jsx('b', { children: gameName(mode) }), jsx('br', {}),
      jsx('span', { className: 'h-faint h-small', children: props.gameOn ? 'A game is already running' : blurb })
    ] })
  ] }, mode)
  return jsxs('div', { className: 'h-menu', ref, role: 'menu', style: { left: 'auto', right: 0 }, children: [
    item('tales', 'game', 'Your agent hosts. Everyone writes a fake answer; spot the truth.'),
    item('agent', 'organization', 'Everyone answers, agents too, and the agents sound human on purpose. Spot them.')
  ] })
}

// ---- people -----------------------------------------------------------------------------------

function People(props) {
  const { room, snap } = props
  return jsxs('div', { className: 'h-col', style: { gap: 2 }, children: [
    jsx('div', { className: 'h-sec', style: { padding: '0 4px 6px' }, children: 'In the room' }),
    (room.members || []).map(p => jsx(Person, { p, key: p.pk })),
    jsx(MyAgentCard, { snap })
  ] })
}

function Person(props) {
  const p = props.p
  const ref = useEnter(false)
  return jsxs('div', { className: 'h-person', ref, children: [
    jsxs('div', { className: 'h-person-row', children: [
      jsx('span', { className: 'h-presence', 'data-on': !!p.online, 'aria-label': p.online ? 'online' : 'away' }),
      jsx('span', { className: 'h-trunc', style: { fontWeight: 600 }, children: p.name }),
      p.you && jsx('span', { className: 'h-faint h-tiny', children: 'you' }),
      p.impostor && jsx(NotVerified, { name: p.name })
    ] }),
    (p.agents || []).map(a => jsxs('div', { className: 'h-agentrow', children: [
      jsx(Face, { face: a.face, pk: a.pk, state: a.state, size: 20, name: a.name }),
      jsxs('div', { className: 'h-grow', style: { minWidth: 0 }, children: [
        jsxs('div', { className: 'h-row', style: { gap: 6, minWidth: 0 }, children: [
          jsx('span', { className: 'h-trunc', children: a.name }),
          a.impostor && jsx(NotVerified, { name: a.name })
        ] }),
        jsx('div', { className: 'h-statepill', children: buildLabel(a, p.you ? 'you' : p.name) || (STATE_LABEL[stateWord(a.state)] + ' · ' + (p.you ? 'your agent' : p.name + "'s agent")) })
      ] }),
      a.budget && a.budget.limit ? jsx(BudgetRing, { budget: a.budget, size: 14, stroke: 2 }) : null
    ] }, a.pk))
  ] })
}

// A member using a name someone else in the room already holds: same rule as the message badge.
function NotVerified(props) {
  return jsx(K.Tip, { label: 'Someone else in this room already uses the name “' + props.name + '”. This is a different key.',
    children: jsxs('span', { className: 'h-impostor h-tiny', role: 'note', children: [jsx(K.Icon, { name: 'shield', size: 11 }), 'not verified'] }) })
}

function MyAgentCard(props) {
  const snap = props.snap
  const a = snap.me.agent
  const w = stateWord(a.state)
  return jsxs('div', { className: 'h-mine', children: [
    jsxs('div', { className: 'h-row', children: [
      jsx(Face, { face: a.face, pk: a.pk, state: a.state, size: 40, name: a.name }),
      jsxs('div', { className: 'h-grow', children: [
        jsx('div', { style: { fontWeight: 600 }, children: a.name || 'Your agent' }),
        jsx('div', { className: 'h-faint h-small', children: STATE_LABEL[w] + (a.note ? ' · ' + a.note : '') })
      ] })
    ] }),
    jsxs('div', { className: 'h-row', children: [
      jsx(BudgetRing, { budget: snap.budget, size: 30, stroke: 3, children: Math.round((snap.budget.pct || 0) * 100) }),
      jsxs('div', { className: 'h-grow h-small', children: [
        jsx('div', { children: fmtTokens(snap.budget.used) + ' / ' + fmtTokens(snap.budget.limit) }),
        jsx('div', { className: 'h-faint', children: snap.budget.pct >= 1 ? 'resting until tomorrow' : 'tokens today' })
      ] })
    ] })
  ] })
}

// ===== ui/55_line.js ============================================================================

// ---------------------------------------------------------------------------------------------
// the private line: you and your own Hermes (tools, memory, approvals), through the gateway.
//
// Nothing in this view is published. What you type goes to the local store; the Xenia gateway
// platform hands it to your Hermes and writes the reply back. Room messages never come in here.
// A reply reaches a room only through "Post to room", which adds a draft you still send yourself.
// ---------------------------------------------------------------------------------------------

function useLine(store, snap) {
  const [data, setData] = useState(null)
  const [err, setErr] = useState('')
  const sum = snap.line || {}
  const load = useCallback(() => P.rest('/line').then(d => { setData(d); setErr('') }, e => setErr(errText(e))), [])
  // the /state snapshot carries the thread's summary; refetch whenever it moves
  useEffect(() => { load() }, [sum.rev, sum.typing, sum.gateway, sum.queued])
  // waiting on a reply: look a little more often than the page does
  const waiting = !!(data && (data.queued > 0 || data.typing))
  useEffect(() => {
    if (!waiting) return
    return P.setInterval(load, 1200)
  }, [waiting])
  return { data, err, load, setData }
}

function LineView(props) {
  const { store, snap } = props
  const { data, err, load, setData } = useLine(store, snap)
  const scroller = useRef(null)
  const stick = useRef(true)
  const seen = useRef(null)
  const msgs = (data && data.messages) || []
  if (data && seen.current === null) seen.current = new Set(msgs.map(m => m.id))
  const fresh = id => {
    if (!seen.current || seen.current.has(id)) return false
    seen.current.add(id)
    return true
  }
  const onScroll = () => {
    const el = scroller.current
    if (el) stick.current = el.scrollHeight - el.scrollTop - el.clientHeight < 80
  }
  const lastId = msgs.length ? msgs[msgs.length - 1].id : ''
  const typing = !!(data && data.typing)
  useLayoutEffect(() => {
    const el = scroller.current
    if (el && stick.current) el.scrollTop = el.scrollHeight
  }, [msgs.length, lastId, typing])

  const send = async text => {
    const m = await store.post('/line/send', { text })
    stick.current = true
    setData(d => d ? Object.assign({}, d, { messages: d.messages.concat([m]), queued: (d.queued || 0) + 1 }) : d)
    load()
  }

  const gatewayDown = data && !data.gateway
  return jsxs(Fragment, { children: [
    jsxs('div', { className: 'h-head', children: [
      jsx(HermesMark, { size: 28 }),
      jsxs('div', { className: 'h-grow h-col', style: { gap: 2 }, children: [
        jsxs('div', { className: 'h-row', children: [
          jsx('h2', { children: 'Your Hermes' }),
          jsxs('span', { className: 'h-private', children: [jsx(K.Icon, { name: 'lock', size: 11 }), 'private'] })
        ] }),
        jsx('div', { className: 'h-faint h-small h-trunc', children: 'Only you and your Hermes see this thread. Nothing here reaches a room unless you post it.' })
      ] })
    ] }),
    jsx('div', { className: 'h-scroll', ref: scroller, onScroll, children: jsxs('div', { className: 'h-timeline', role: 'log', 'aria-live': 'polite', children: [
      err && jsx(Notice, { icon: 'warning', role: 'alert', children: err }),
      !data && !err && jsx('div', { className: 'h-empty', children: 'Opening your private line…' }),
      data && msgs.length === 0 && jsx(LineEmpty, {}),
      msgs.map((m, i) => jsx(LineMessage, { m, prev: msgs[i - 1], snap, store, gatewayDown, animate: fresh(m.id) }, m.id)),
      typing && jsx(LineTyping, {}, 'typing')
    ] }) }),
    jsxs('div', { className: 'h-composer', children: [
      gatewayDown && jsx('div', { style: { marginBottom: 8 }, children: jsx(Notice, { icon: 'clock', children:
        'Your Hermes gateway isn’t running for this profile, so messages wait here. Open a chat in Hermes, or run `hermes gateway run`, and they go through.' }) }),
      jsx(LineComposer, { onSend: send })
    ] })
  ] })
}

function HermesMark(props) {
  const s = props.size || 28
  return jsx('span', { className: 'h-hmark', 'aria-hidden': true, style: { width: s, height: s, fontSize: Math.round(s * 0.46) }, children: 'H' })
}

function LineEmpty() {
  return jsxs('div', { className: 'h-empty', children: [
    jsx(HermesMark, { size: 44 }),
    jsx('b', { children: 'A private line to your own Hermes' }),
    jsx('div', { style: { maxWidth: 420 }, children: 'Ask it anything, with its tools and memory, without leaving Xenia. Room chat never comes in here. If you want it to see something from a room, paste it yourself.' })
  ] })
}

function LineMessage(props) {
  const { m, prev, snap, store } = props
  const ref = useEnter(props.animate)
  const mine = m.role === 'owner'
  const first = !prev || prev.role !== m.role || m.created_at - prev.created_at > 300
  let status = null
  if (mine && m.status === 'queued') status = props.gatewayDown ? 'waiting for your gateway' : 'sending…'
  else if (mine && m.status === 'failed') status = 'not delivered'
  return jsx('div', { ref, children: jsxs('div', { className: cx('h-msg', 'h-lmsg'), 'data-role': mine ? 'owner' : 'hermes', 'data-first': first, children: [
    jsx('div', { className: 'h-gutter', children: first ? (mine ? jsx(Initial, { name: snap.me.name || 'You' }) : jsx(HermesMark, { size: 28 })) : null }),
    jsxs('div', { style: { minWidth: 0 }, children: [
      first && jsxs('div', { className: 'h-meta', children: [
        jsx('b', { children: mine ? 'You' : 'Your Hermes' }),
        jsx('span', { className: 'h-faint h-tiny', children: fmtTime(m.created_at) })
      ] }),
      mine ? jsx('div', { className: 'h-text', children: m.text })
        : jsx('div', { className: 'h-bubble', children: jsx('div', { className: 'h-text', children: m.text }) }),
      status && jsx('div', { className: 'h-faint h-tiny', 'data-status': m.status, children: status }),
      !mine && jsx(PostToRoom, { m, snap, store })
    ] })
  ] }) })
}

function LineTyping() {
  const ref = useEnter(true)
  return jsx('div', { ref, children: jsxs('div', { className: 'h-msg h-lmsg', 'data-role': 'hermes', 'data-first': true, children: [
    jsx('div', { className: 'h-gutter', children: jsx(HermesMark, { size: 28 }) }),
    jsxs('div', { className: 'h-typing', role: 'status', 'aria-label': 'Your Hermes is working', children: [0, 1, 2].map(i => jsx('i', { style: { animationDelay: (i * 0.16) + 's' } }, i)) })
  ] }) })
}

// "Post to room": the reply becomes a draft in that room's tray. You still read it and press Send.
function PostToRoom(props) {
  const { m, snap, store } = props
  const [open, setOpen] = useState(false)
  const ref = useRef(null)
  const rooms = snap.rooms || []
  useEffect(() => {
    if (!open) return
    const away = e => { if (ref.current && !ref.current.contains(e.target)) setOpen(false) }
    const esc = e => { if (e.key === 'Escape') setOpen(false) }
    const off1 = P.listen(document, 'pointerdown', away)
    const off2 = P.listen(document, 'keydown', esc)
    return () => { off1(); off2() }
  }, [open])
  if (!rooms.length) return null
  const post = async room => {
    setOpen(false)
    try {
      const out = await store.post('/line/post', { id: m.id, room: room.id })
      P.toast('info', 'Draft added to ' + (out.room_name || room.name) + '. Read it and send it from the room.' + (out.truncated ? ' It was cut to 1,200 characters.' : ''))
    } catch (_) { /* toasted */ }
  }
  return jsxs('div', { className: 'h-lactions', ref, style: { position: 'relative' }, children: [
    jsx(K.Tip, { label: 'Adds a draft to a room. Nothing is sent until you press Send there.', children:
      jsx(K.Button, { variant: 'ghost', size: 'sm', 'aria-expanded': open, onClick: () => setOpen(!open),
        children: jsxs(Fragment, { children: [jsx(K.Icon, { name: 'reply', size: 13 }), 'Post to room…'] }) }) }),
    open && jsx('div', { className: 'h-menu', role: 'menu', style: { bottom: 'auto', top: 'calc(100% + 4px)' }, children: rooms.map(r =>
      jsxs('button', { type: 'button', role: 'menuitem', onClick: () => post(r), children: [
        jsx('span', { className: 'h-hash', children: '#' }),
        jsx('span', { className: 'h-grow h-trunc', children: r.name })
      ] }, r.id)) })
  ] })
}

function LineComposer(props) {
  const [text, setText] = useState('')
  const [busy, setBusy] = useState(false)
  const ta = useRef(null)
  const send = async () => {
    const t = text.trim()
    if (!t || busy) return
    setBusy(true)
    setText('')
    try { await props.onSend(t) } catch (_) { setText(t) }
    setBusy(false)
    ta.current && ta.current.focus()
  }
  useLayoutEffect(() => {
    const el = ta.current
    if (!el) return
    el.style.height = 'auto'
    el.style.height = Math.min(160, el.scrollHeight) + 'px'
  }, [text])
  return jsxs('div', { className: 'h-compose-box', 'data-private': true, children: [
    jsx(K.Icon, { name: 'lock', size: 13 }),
    jsx('textarea', { ref: ta, rows: 1, value: text, maxLength: 8000, placeholder: 'Message your Hermes (private)', 'aria-label': 'Message your Hermes',
      onChange: e => setText(e.target.value),
      onKeyDown: e => { if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) { e.preventDefault(); send() } } }),
    jsx(K.Button, { variant: 'primary', size: 'icon', 'aria-label': 'Send to your Hermes', disabled: !text.trim() || busy, onClick: send,
      children: jsx(K.Icon, { name: 'send', size: 14 }) })
  ] })
}

// right rail while the private line is open: who is who, in one glance
function LineAbout(props) {
  const a = props.snap.me.agent
  return jsxs('div', { className: 'h-col', style: { gap: 10 }, children: [
    jsx('div', { className: 'h-sec', style: { padding: '0 4px' }, children: 'Two different agents' }),
    jsxs('div', { className: 'h-mine', style: { marginTop: 0 }, children: [
      jsxs('div', { className: 'h-row', children: [jsx(HermesMark, { size: 24 }), jsx('b', { children: 'Your Hermes' })] }),
      jsx('div', { className: 'h-faint h-small', children: 'Full tools and memory, under your approvals. Hears only you, here. Never reads rooms.' })
    ] }),
    jsxs('div', { className: 'h-mine', style: { marginTop: 0 }, children: [
      jsxs('div', { className: 'h-row', children: [jsx(Face, { face: a.face, pk: a.pk, state: a.state, size: 24, name: a.name }), jsx('b', { children: a.name || 'Your room agent' })] }),
      jsx('div', { className: 'h-faint h-small', children: 'Chats in rooms. No tools, no memory, no files: a stranger can’t make it do anything that matters.' })
    ] })
  ] })
}

// ===== ui/60_tales.js ===========================================================================

// ---------------------------------------------------------------------------------------------
// Tall Tales: the host agent asks an obscure question with a real answer; everyone (people and
// agents) writes a convincing fake; people vote for the truth. A team is a person + their agent.
// Pinned above the composer while a game runs.
// ---------------------------------------------------------------------------------------------

const LETTERS = 'ABCDEFGHIJKL'

// Who's the Agent? runs on the same rounds and panel: everyone answers a prompt about their own life,
// agents included and trying to pass as people; people flag the answers they think an agent wrote.
const GAME_NAME = { tales: 'Tall Tales', agent: 'Who’s the Agent?' }
function gameName(mode) { return GAME_NAME[mode] || GAME_NAME.tales }

function TallTales(props) {
  const { store, room, game, book } = props
  const [hidden, setHidden] = useState(false)
  const running = game.phase !== 'end'
  const now = useNow(250, running && game.ends_at > 0)
  if (hidden) return null

  const hostLabel = game.you_host ? 'Your agent is hosting' : 'Hosted by ' + (game.host_name || 'an agent')
  const round = game.n ? 'Round ' + game.n + ' of ' + game.rounds : 'Getting ready'

  let body = null
  const who = game.mode === 'agent'
  if (game.phase === 'starting') body = jsx('div', { className: 'h-muted', children: (game.host_name || 'The host') + (who ? ' is picking prompts…' : ' is writing questions…') })
  else if (game.phase === 'fakes') body = jsx(FakePhase, { store, room, game, quiet: props.quiet })
  else if (game.phase === 'vote') body = who ? jsx(FlagPhase, { store, room, game }) : jsx(VotePhase, { store, room, game })
  else if (game.phase === 'reveal') body = who ? jsx(WhoRevealPhase, { game, book }) : jsx(RevealPhase, { game, book })
  else if (game.phase === 'end') body = jsx('div', { className: 'h-muted', children: game.stale ? 'The host went quiet, so the game is over.' : game.aborted ? 'The game stopped early.' : 'That’s the game. Final scores:' })

  return jsxs('section', { className: 'h-tales', 'aria-label': gameName(game.mode), children: [
    jsxs('div', { className: 'h-row', children: [
      jsx(K.Icon, { name: 'game', size: 16 }),
      jsxs('div', { className: 'h-grow', children: [
        jsx('div', { className: 'h-kicker h-sec', children: gameName(game.mode) + ' · ' + round }),
        jsx('div', { className: 'h-faint h-small', children: hostLabel })
      ] }),
      running && game.ends_at > 0 && jsx(Countdown, { game, now }),
      // Always closable: a host that vanished mid-game must never pin a panel over the room.
      jsx(K.Button, { variant: 'ghost', size: 'sm', onClick: () => setHidden(true), children: running ? 'Hide' : 'Close' })
    ] }),
    game.q && game.phase !== 'end' && jsx('div', { className: 'h-tales-q', children: game.q }),
    body,
    jsx(Scoreboard, { game, room })
  ] })
}

// The ring empties as the phase runs out. Its full length is the phase duration the host sent
// (game.secs); older hosts don't send it, so fall back to the longest remaining time seen.
function Countdown(props) {
  const { game, now } = props
  const total = useRef({ key: '', max: 1 })
  const key = game.gid + ':' + game.n + ':' + game.phase
  const left = Math.max(0, game.ends_at - now)
  if (total.current.key !== key) total.current = { key, max: Math.max(1, left) }
  else total.current.max = Math.max(total.current.max, left)
  if (game.secs > 0) total.current.max = Math.max(game.secs, left, 1)
  const secs = Math.ceil(left)
  return jsx(Ring, { pct: left / total.current.max, from: 1, size: 34, stroke: 3, spring: SPRING.tick, tone: secs <= 5 ? 'warn' : '',
    label: secs + ' seconds left', children: secs })
}

function FakePhase(props) {
  const { store, room, game } = props
  const [text, setText] = useState('')
  const [busy, setBusy] = useState(false)
  const who = game.mode === 'agent'
  if (game.my_fake) {
    return jsxs('div', { className: 'h-col', style: { gap: 4 }, children: [
      jsxs('div', { children: [who ? 'Your answer is in: ' : 'Your fake is in: ', jsx('b', { children: '“' + game.my_fake + '”' })] }),
      jsx('div', { className: 'h-faint h-small', children: game.fakes_in + ' answer' + (game.fakes_in === 1 ? '' : 's') + ' in so far. ' +
        (who ? 'Your agent is answering too, and it’s trying to pass as a person.' : 'Your agent writes one too.') })
    ] })
  }
  const submit = async () => {
    const t = text.trim()
    if (!t || busy) return
    setBusy(true)
    try { await store.post('/game/fake', { room: room.id, gid: game.gid, n: game.n, text: t }) } catch (_) { /* toasted */ }
    setBusy(false)
  }
  return jsxs('div', { className: 'h-col', style: { gap: 6 }, children: [
    jsx('div', { className: 'h-faint h-small', children: who
      ? 'Answer as yourself. Agents answer too, and they’re trying to sound human. Or sound like a bot and fool the room.'
      : 'Write a believable fake answer. You score for everyone it fools.' }),
    jsxs('div', { className: 'h-row', children: [
      jsx('div', { className: 'h-grow', children: jsx(K.Input, { value: text, maxLength: 80, autoFocus: !props.quiet,
        placeholder: who ? 'Your answer' : 'Your fake answer', 'aria-label': who ? 'Your answer' : 'Your fake answer',
        onChange: e => setText(e.target.value), onKeyDown: e => { if (e.key === 'Enter') { e.preventDefault(); submit() } } }) }),
      jsx(K.Button, { variant: 'primary', disabled: !text.trim() || busy, onClick: submit, children: 'Submit' })
    ] })
  ] })
}

function VotePhase(props) {
  const { store, room, game } = props
  const [busy, setBusy] = useState('')
  const blocked = new Set(game.blocked || [])
  const vote = async id => {
    if (game.my_vote || busy) return
    setBusy(id)
    try { await store.post('/game/vote', { room: room.id, gid: game.gid, n: game.n, option: id }) } catch (_) { /* toasted */ }
    setBusy('')
  }
  return jsxs('div', { className: 'h-col', style: { gap: 6 }, children: [
    jsx('div', { className: 'h-faint h-small', children: game.my_vote ? 'Vote in. ' + game.votes_in + ' voted so far.' : 'Which one is true? You can’t pick your own team’s answers.' }),
    jsx('div', { className: 'h-opts', role: 'radiogroup', 'aria-label': 'Answers', children: (game.options || []).map((o, i) =>
      jsxs('button', { type: 'button', className: 'h-opt', role: 'radio', 'aria-checked': game.my_vote === o.id,
        'data-picked': game.my_vote === o.id || busy === o.id, disabled: blocked.has(o.id) || (!!game.my_vote && game.my_vote !== o.id),
        onClick: () => vote(o.id), children: [
          jsx('span', { className: 'h-letter', children: LETTERS[i] }),
          jsx('span', { className: 'h-grow', children: o.text }),
          blocked.has(o.id) && jsx('span', { className: 'h-faint h-tiny', children: 'your team' })
        ] }, o.id)) })
  ] })
}

// Who's the Agent?: tap every answer you think an agent wrote, then lock in. Unflagged means "a person".
function FlagPhase(props) {
  const { store, room, game } = props
  const [picked, setPicked] = useState(() => new Set())
  const [busy, setBusy] = useState(false)
  const blocked = new Set(game.blocked || [])
  const locked = !!game.my_vote
  const mine = new Set(game.my_picks || [])
  const toggle = id => {
    if (locked || blocked.has(id)) return
    const next = new Set(picked)
    next.has(id) ? next.delete(id) : next.add(id)
    setPicked(next)
  }
  const lock = async () => {
    if (locked || busy) return
    setBusy(true)
    try { await store.post('/game/vote', { room: room.id, gid: game.gid, n: game.n, agents: Array.from(picked) }) } catch (_) { /* toasted */ }
    setBusy(false)
  }
  const flagged = locked ? mine : picked
  return jsxs('div', { className: 'h-col', style: { gap: 6 }, children: [
    jsx('div', { className: 'h-faint h-small', children: locked
      ? 'Locked in. ' + game.votes_in + ' voted so far.'
      : 'Which ones did an agent write? Tap each one you suspect. Anything you skip counts as a person.' }),
    jsx('div', { className: 'h-opts', role: 'group', 'aria-label': 'Answers', children: (game.options || []).map((o, i) =>
      jsxs('button', { type: 'button', className: 'h-opt', 'aria-pressed': flagged.has(o.id), 'data-picked': flagged.has(o.id),
        disabled: blocked.has(o.id) || locked, onClick: () => toggle(o.id), children: [
          jsx('span', { className: 'h-letter', children: LETTERS[i] }),
          jsx('span', { className: 'h-grow', children: o.text }),
          blocked.has(o.id) ? jsx('span', { className: 'h-faint h-tiny', children: 'your team' })
            : jsx('span', { className: 'h-whotag', 'data-on': flagged.has(o.id), children: flagged.has(o.id) ? 'agent' : 'person' })
        ] }, o.id)) }),
    !locked && jsx('div', { className: 'h-actions', children: jsx(K.Button, { variant: 'primary', size: 'sm', disabled: busy, onClick: lock,
      children: busy ? 'Locking in…' : picked.size ? 'Lock in · ' + picked.size + ' agent' + (picked.size === 1 ? '' : 's') : 'Lock in · all people' }) })
  ] })
}

function WhoRevealPhase(props) {
  const { game } = props
  const rv = game.reveal || {}
  const book = Object.assign({}, props.book)
  Object.keys(rv.names || {}).forEach(pk => { if (!book[pk]) book[pk] = { name: String(rv.names[pk]) } })
  const authors = rv.authors || {}
  const kinds = rv.kinds || {}
  const flags = rv.picks || {}
  const voters = rv.voters || []
  const points = rv.points || {}
  const team = pk => (book[pk] && book[pk].agent && book[pk].owner) || pk
  return jsxs('div', { className: 'h-col', style: { gap: 6 }, children: [
    jsx('div', { className: 'h-opts', children: (game.options || []).map((o, i) => {
      const author = authors[o.id] || ''
      const agent = kinds[o.id] === 'agent'
      const flaggedBy = flags[o.id] || []
      // everyone who voted and could call this one (not the author's own team) but didn't flag it
      const missed = voters.filter(v => !flaggedBy.includes(v) && team(v) !== team(author))
      const right = agent ? flaggedBy : missed
      const wrong = agent ? missed : flaggedBy
      const verdict = []
      if (right.length) verdict.push((agent ? 'spotted by ' : 'read right by ') + joinNames(right.map(pk => whoLabel(book, pk))))
      if (wrong.length) verdict.push('fooled ' + joinNames(wrong.map(pk => whoLabel(book, pk))))
      return jsxs('div', { className: 'h-opt', 'data-agent': agent, children: [
        jsx('span', { className: 'h-letter', children: LETTERS[i] }),
        jsxs('span', { className: 'h-grow h-col', style: { gap: 1 }, children: [
          jsx('span', { children: o.text }),
          jsx('span', { className: 'h-faint h-small', children: whoLabel(book, author) + (agent ? ' · an agent' : ' · a person') + (verdict.length ? ' · ' + verdict.join(' · ') : '') })
        ] }),
        jsx('span', { className: 'h-whotag', 'data-on': agent, children: agent ? 'agent' : 'person' })
      ] }, o.id)
    }) }),
    Object.keys(points).length > 0 && jsx('div', { className: 'h-small', children: 'This round: ' + Object.keys(points).map(t => teamName(game, book, t) + ' +' + points[t]).join(' · ') })
  ] })
}

function RevealPhase(props) {
  const { game } = props
  const rv = game.reveal || {}
  // Names the host sent fill gaps for players who have left the room since.
  const book = Object.assign({}, props.book)
  Object.keys(rv.names || {}).forEach(pk => { if (!book[pk]) book[pk] = { name: String(rv.names[pk]) } })
  const authors = rv.authors || {}
  const picks = rv.picks || {}
  const points = rv.points || {}
  const lucky = rv.lucky || []
  const opts = game.options || []
  return jsxs('div', { className: 'h-col', style: { gap: 6 }, children: [
    jsx('div', { className: 'h-opts', children: opts.map((o, i) => {
      const truth = o.id === rv.truth
      const by = String(authors[o.id] || '').split(',').filter(Boolean).map(pk => whoLabel(book, pk))
      const fooled = (picks[o.id] || []).map(pk => whoLabel(book, pk))
      return jsxs('div', { className: 'h-opt', 'data-truth': truth, children: [
        jsx('span', { className: 'h-letter', children: truth ? '✓' : LETTERS[i] }),
        jsxs('span', { className: 'h-grow h-col', style: { gap: 1 }, children: [
          jsx('span', { children: o.text }),
          jsx('span', { className: 'h-faint h-small', children: truth
            ? (fooled.length ? 'The truth. Found by ' + joinNames(fooled) : 'The truth. Nobody found it')
            : 'Fake by ' + (by.length ? joinNames(by) : 'someone') + (fooled.length ? ' · fooled ' + joinNames(fooled) : '') })
        ] })
      ] }, o.id)
    }) }),
    lucky.length > 0 && jsx('div', { className: 'h-faint h-small', children: joinNames(lucky.map(pk => whoLabel(book, pk))) + ' guessed the real answer while writing a fake. Lucky.' }),
    Object.keys(points).length > 0 && jsx('div', { className: 'h-small', children: 'This round: ' + Object.keys(points).map(t => teamName(game, book, t) + ' +' + points[t]).join(' · ') })
  ] })
}

function teamName(game, book, pk) {
  const person = (game.team_names && game.team_names[pk]) || (book[pk] && book[pk].name) || 'Someone'
  const agent = Object.values(book).find(b => b.agent && b.owner === pk)
  return agent ? person + ' + ' + agent.name : person
}

function Scoreboard(props) {
  const { game, room } = props
  const book = nameBook(room, null)
  const scores = game.scores || {}
  const teams = Object.keys(Object.assign({}, game.team_names || {}, scores))
  if (!teams.length) return null
  teams.sort((a, b) => (scores[b] || 0) - (scores[a] || 0))
  const you = (room.members || []).find(p => p.you)
  return jsx('div', { className: 'h-score', 'aria-label': 'Scores', children: teams.map(t =>
    jsxs('span', { className: 'h-team', 'data-you': !!(you && you.pk === t), children: [
      jsx('span', { children: teamName(game, book, t) }), jsx('b', { children: scores[t] || 0 })
    ] }, t)) })
}

// ===== ui/65_cards.js ===========================================================================

// ---------------------------------------------------------------------------------------------
// Chat cards (Desktop): `::xenia-offer{id="…"}` and `::xenia-tales{room="…"}` rendered inside a
// normal Hermes conversation. The model writes the attributes, so they are untrusted: each is
// checked for shape, then looked up in what the backend returns, and a miss is a small quiet chip.
// Text is only ever rendered as text. Buttons call the same backend routes as the Xenia page.
// ---------------------------------------------------------------------------------------------

const OFFER_ID_RE = /^[0-9a-f]{64}$/
const ROOM_ID_RE = /^[0-9a-f]{8,64}$/

// A hidden turn that tells the agent what the owner just did. `window.hermes.send` is the SDK's
// documented, rate-limited way for a widget to talk back; where the host does not provide it to a
// plugin component (it is a preview-frame API), nothing is sent and the route call is the whole
// effect. Limits per the SDK: 500 characters, one per second. Never a visible fallback.
let lastTell = 0
function tellAgent(text) {
  const bridge = typeof window !== 'undefined' ? window.hermes : null
  if (!bridge || typeof bridge.send !== 'function') return Promise.resolve({ ok: false, error: 'unavailable' })
  const now = Date.now()
  if (now - lastTell < 1100) return Promise.resolve({ ok: false, error: 'throttled' })
  lastTell = now
  try { return Promise.resolve(bridge.send(String(text).slice(0, 500))).catch(() => ({ ok: false, error: 'undelivered' })) } catch (_) { return Promise.resolve({ ok: false, error: 'undelivered' }) }
}

// Poll `load` while mounted (and enabled); keeps the last good value across a failed poll.
function usePolled(load, key, ms, enabled) {
  const [s, setS] = useState({ ready: false, data: null, status: 0 })
  const loadRef = useRef(load)
  loadRef.current = load
  const [kick, setKick] = useState(0)
  useEffect(() => {
    if (!enabled) return
    let dead = false
    let busy = false
    const run = async () => {
      if (busy || dead) return
      busy = true
      try { const data = await loadRef.current(); if (!dead) setS({ ready: true, data, status: 0 }) }
      catch (e) { if (!dead) setS(prev => ({ ready: true, data: prev.data, status: errStatus(e) || 500 })) }
      busy = false
    }
    run()
    const stop = P.setInterval(() => { if (!document.hidden) run() }, ms)
    return () => { dead = true; if (stop) stop() }
  }, [key, enabled, kick])
  return [s, () => setKick(k => k + 1)]
}

// POST helper for a card: toast the engine's own words on failure, then re-poll.
function cardPost(refresh) {
  return {
    async post(path, body, okMsg) {
      try {
        const out = await P.rest(path, { method: 'POST', body: body || {} })
        if (okMsg) P.toast('info', okMsg)
        refresh()
        return out
      } catch (e) { P.toast('error', errText(e)); throw e }
    }
  }
}

function CardChip(props) {
  return jsxs('span', { className: 'hx h-chip h-cardchip', role: 'note', children: [jsx(K.Icon, { name: 'home', size: 12 }), props.children || 'Xenia: not found'] })
}

// ---- offer ------------------------------------------------------------------------------------

// The offer's message lives in its room's transcript (title, pitch, owner); the local list only
// holds offers still waiting, building or ready. Fetching a room's state marks it read, so the
// room is only fetched when we have nothing cached or the offer changed state.
function useOffer(id, enabled) {
  const cache = useRef({ id: '', m: null, room: null })
  const load = async () => {
    const snap = await P.rest('/state')
    const rooms = snap.rooms || []
    const pend = (snap.offers || []).find(o => o.id === id)
    const c = cache.current.id === id ? cache.current : { id, m: null, room: null }
    const final = c.m && (c.m.state === 'shared' || c.m.state === 'declined')
    if (!c.m || (pend ? pend.status !== c.m.state : !final)) {
      const order = pend ? rooms.filter(r => r.id === pend.room) : rooms.slice(0, 8)
      c.m = null
      for (const r of order) {
        const s = await P.rest('/state?room=' + encodeURIComponent(r.id))
        const m = ((s.room && s.room.messages) || []).find(x => x.t === 'offer' && x.id === id)
        if (m) { c.m = m; c.room = { id: r.id, name: r.name }; break }
      }
    }
    cache.current = c
    if (!c.m) return null
    return { m: c.m, room: c.room, state: pend ? pend.status : c.m.state }
  }
  return usePolled(load, id, 2500, enabled)
}

function OfferDirective(props) {
  const id = String((props.attrs && props.attrs.id) || '').toLowerCase()
  const valid = OFFER_ID_RE.test(id)
  const [res, refresh] = useOffer(id, valid && !props.streaming)
  if (!valid) return jsx(CardChip, {})
  if (!res.ready) return jsx(CardChip, { children: 'Xenia…' })
  if (res.status === 404) return jsx(CardChip, { children: 'Xenia: not available' })
  if (!res.data) return jsx(CardChip, {})
  return jsx(OfferChatCard, { d: res.data, refresh })
}

function OfferChatCard(props) {
  const { m, room, state } = props.d
  const [busy, setBusy] = useState('')
  const [sure, setSure] = useState(false)
  const [review, setReview] = useState(false)
  const [prompt, setPrompt] = useState(null)
  const enter = useEnter(true)
  const cs = cardPost(props.refresh)
  const f = faceFor(m.face, m.pk)
  const owner = m.owner_name || 'its owner'

  const run = async (name, fn) => {
    if (busy) return
    setBusy(name)
    try { await fn() } catch (_) { /* toasted */ }
    setBusy('')
  }
  // Accept never hands anything over unseen: it opens the same review as the Xenia page, with the
  // full task in an editable box. The hand-off (a fresh chat with the task in its composer) happens there.
  const decline = () => run('decline', async () => {
    await cs.post('/offers/answer', { offer: m.id, accept: false })
    tellAgent('Xenia: I passed on offer ' + m.id.slice(0, 12) + '. No action needed.')
  })
  // Sharing goes through the same dialog as the Xenia page: preview, size, secret scan and source.
  const shared = () => tellAgent('Xenia: I shared the build for offer ' + m.id.slice(0, 12) + ' with the room.')

  let status = null
  let actions = null
  if (m.yours) {
    if (state === 'open') actions = [
      jsx(K.Button, { variant: 'primary', size: 'sm', disabled: !!busy, onClick: () => setReview(true), children: 'Review & build' }, 'a'),
      jsx(K.Button, { variant: 'ghost', size: 'sm', disabled: !!busy, onClick: decline, children: 'Not now' }, 'n')]
    else if (state === 'building') status = 'Your Hermes is building it. When the file is saved, you can share it here.'
    else if (state === 'ready') actions = [
      jsx(K.Button, { variant: 'primary', size: 'sm', onClick: () => setSure(true), children: 'Preview & share' }, 's')]
    else if (state === 'shared') status = 'Shared with #' + room.name + '.'
    else if (state === 'declined') status = 'You passed on this one.'
  } else {
    status = state === 'open' ? 'Waiting for ' + owner + ' to decide.'
      : state === 'building' || state === 'ready' ? owner + ' is building it.'
      : state === 'shared' ? owner + ' shared it.' : state === 'declined' ? owner + ' passed.' : null
  }

  return jsxs('div', { ref: enter, className: 'hx h-chatcard h-agent', style: { '--hue': f.hue }, 'data-state': state, children: [
    jsxs('div', { className: 'h-row', children: [
      jsx(Face, { face: m.face, pk: m.pk, state: state === 'open' && m.yours ? 'system: waiting' : state === 'building' ? 'activity: working' : 'activity: idle', size: 28, name: m.name }),
      jsxs('div', { className: 'h-grow', style: { minWidth: 0 }, children: [
        jsx('div', { className: 'h-kicker', children: 'Xenia · ' + room.name + ' · ' + state }),
        jsx('h4', { children: m.title })
      ] })
    ] }),
    jsx('div', { className: 'h-text', children: m.pitch }),
    status && jsx('div', { className: 'h-faint h-small', children: status }),
    actions && jsx('div', { className: 'h-actions', children: actions }),
    review && jsx(ReviewDialog, { m, store: cs, onClose: () => { setReview(false); props.refresh() }, onPrompt: setPrompt }),
    sure && jsx(ShareDialog, { m, store: cs, room, onShared: shared, onClose: () => { setSure(false); props.refresh() } }),
    prompt && jsx(PromptDialog, { prompt, onClose: () => setPrompt(null) })
  ] })
}

// ---- Tall Tales -------------------------------------------------------------------------------

function TalesDirective(props) {
  const room = String((props.attrs && props.attrs.room) || '').toLowerCase()
  const valid = ROOM_ID_RE.test(room)
  const load = async () => {
    const snap = await P.rest('/state?room=' + encodeURIComponent(room))
    if (!(snap.rooms || []).some(r => r.id === room) || !snap.room || snap.room.id !== room) return null
    return { room: snap.room, me: snap.me }
  }
  // the same one-second rhythm as the Xenia page while a game runs
  const [res, refresh] = usePolled(load, room, 1000, valid && !props.streaming)
  if (!valid) return jsx(CardChip, {})
  if (!res.ready) return jsx(CardChip, { children: 'Xenia…' })
  if (res.status === 404) return jsx(CardChip, { children: 'Xenia: not available' })
  if (!res.data) return jsx(CardChip, {})
  return jsx(TalesChatCard, { room: res.data.room, me: res.data.me, game: res.data.room.game, refresh })
}

function TalesChatCard(props) {
  const { room, me, game } = props
  const enter = useEnter(true)
  const store = cardPost(props.refresh)
  const book = nameBook(room, me)
  return jsx('div', { ref: enter, className: 'hx h-chatcard-wrap', children:
    game
      ? jsx(TallTales, { store, room, game, book, quiet: true }, game.gid)
      : jsxs('div', { className: 'h-chatcard', children: [
          jsx('div', { className: 'h-kicker', children: 'Xenia · ' + room.name }),
          jsx('div', { className: 'h-muted', children: 'No Tall Tales game is running in this room.' })
        ] }) })
}

// ===== ui/70_lobby.js ===========================================================================

// ---------------------------------------------------------------------------------------------
// Lobby: your interest card (previewed exactly before it is published), then public rooms and
// people sorted by how many interests you share.
// ---------------------------------------------------------------------------------------------

function Lobby(props) {
  const { store, snap } = props
  const lobby = snap.lobby || { rooms: [], people: [], at: 0 }
  const [busy, setBusy] = useState(false)
  const [joining, setJoining] = useState('')
  const asked = useRef(false)

  const refresh = async () => {
    setBusy(true)
    try { await store.post('/lobby/refresh', {}) } catch (_) { /* toasted */ }
    setBusy(false)
  }
  // first visit with an empty lobby: look around once by ourselves
  useEffect(() => { if (!asked.current && !lobby.at) { asked.current = true; refresh() } }, [])

  const join = async r => {
    setJoining(r.id)
    try { await store.post('/rooms/join', { room: r.id }, 'Joined ' + r.name); store.setRoom(r.id) } catch (_) { /* toasted */ }
    setJoining('')
  }

  const byOverlap = (a, b) => (b.overlap || []).length - (a.overlap || []).length || (b.at || 0) - (a.at || 0)
  const rooms = (lobby.rooms || []).slice().sort(byOverlap)
  const people = (lobby.people || []).slice().sort(byOverlap)

  return jsx('div', { className: 'h-scroll', children: jsxs('div', { className: 'h-pane', children: [
    jsxs('div', { className: 'h-row', children: [
      jsxs('div', { className: 'h-grow', children: [
        jsx('h1', { children: 'Lobby' }),
        jsx('div', { className: 'h-muted', children: 'Public rooms and people on Xenia, closest interests first.' })
      ] }),
      jsx(K.Button, { variant: 'secondary', size: 'sm', disabled: busy, onClick: refresh, children: jsxs(Fragment, { children: [
        jsx(K.Icon, { name: 'refresh', size: 13, spinning: busy }), busy ? 'Looking…' : 'Refresh'] }) })
    ] }),
    jsx(CardSection, { store, snap }),
    jsxs('section', { className: 'h-col', style: { gap: 10 }, children: [
      jsxs('div', { className: 'h-row', children: [
        jsx('h3', { className: 'h-grow', children: 'Rooms' }),
        lobby.at ? jsx('span', { className: 'h-faint h-small', children: 'updated ' + fmtAgo(lobby.at) }) : null
      ] }),
      rooms.length === 0 ? jsx('div', { className: 'h-faint', children: busy ? 'Asking the relays…' : 'No public rooms found yet. Start one and it shows up here for others.' })
        : jsx('div', { className: 'h-list', children: rooms.map(r => jsx(LobbyRoom, { r, joining: joining === r.id, onJoin: () => join(r), onOpen: () => store.setRoom(r.id) }, r.id)) })
    ] }),
    jsxs('section', { className: 'h-col', style: { gap: 10 }, children: [
      jsx('h3', { children: 'People' }),
      people.length === 0 ? jsx('div', { className: 'h-faint', children: busy ? 'Asking the relays…' : 'Nobody has published a card that matches yet.' })
        : jsx('div', { className: 'h-list', children: people.map(p => jsx(LobbyPerson, { p }, p.pk)) })
    ] })
  ] }) })
}

function LobbyRoom(props) {
  const r = props.r
  const ref = useEnter(false)
  const n = (r.overlap || []).length
  return jsxs('div', { className: 'h-item', ref, children: [
    jsx('span', { className: 'h-hash', style: { fontSize: 18, lineHeight: '22px' }, children: '#' }),
    jsxs('div', { className: 'h-grow h-col', style: { gap: 4 }, children: [
      jsxs('div', { className: 'h-row', children: [
        jsx('b', { className: 'h-trunc', children: r.name }),
        n > 0 && jsx('span', { className: 'h-faint h-tiny', children: n + ' shared interest' + (n === 1 ? '' : 's') })
      ] }),
      r.about && jsx('div', { className: 'h-muted h-small', children: r.about }),
      jsx(Chips, { items: r.interests, hits: r.overlap })
    ] }),
    r.joined ? jsx(K.Button, { variant: 'ghost', size: 'sm', onClick: props.onOpen, children: 'Open' })
      : jsx(K.Button, { variant: 'secondary', size: 'sm', disabled: props.joining, onClick: props.onJoin, children: props.joining ? 'Joining…' : 'Join' })
  ] })
}

function LobbyPerson(props) {
  const p = props.p
  return jsxs('div', { className: 'h-item', children: [
    jsx(Initial, { name: p.name }),
    jsxs('div', { className: 'h-grow h-col', style: { gap: 4 }, children: [
      jsxs('div', { className: 'h-row', children: [
        jsx('b', { className: 'h-trunc', children: p.name }),
        p.at ? jsx('span', { className: 'h-faint h-tiny', children: fmtAgo(p.at) }) : null
      ] }),
      p.line && jsx('div', { className: 'h-muted h-small', children: p.line }),
      jsx(Chips, { items: p.interests, hits: p.overlap })
    ] }),
    p.agent && jsxs('div', { className: 'h-row', style: { gap: 6 }, title: p.agent + ' is ' + p.name + "'s agent", children: [
      jsx(Face, { face: p.face, pk: p.pk, state: 'activity: idle', size: 24, name: p.agent }),
      jsx('span', { className: 'h-small h-muted', children: p.agent })
    ] })
  ] })
}

// What gets published, shown before it is: the rendered card and the exact JSON.
function CardSection(props) {
  const { store, snap } = props
  const [preview, setPreview] = useState(null)
  const [raw, setRaw] = useState(false)
  const [busy, setBusy] = useState(false)
  const s = snap.settings
  const key = JSON.stringify([s.display_name, s.line, s.interests, s.agent_name, s.face])
  useEffect(() => { P.rest('/card/preview').then(setPreview, () => setPreview(null)) }, [key])
  const publish = async () => {
    setBusy(true)
    try {
      const out = await store.post('/card/publish', {})
      P.toast('info', 'Card published to ' + out.accepted + ' of ' + out.relays + ' relays')
    } catch (_) { /* toasted */ }
    setBusy(false)
  }
  const published = s.card_published_at > 0
  const c = preview || { name: s.display_name, line: s.line, interests: s.interests, agent: { name: s.agent_name, face: s.face, pk: snap.me.agent.pk } }
  return jsxs('section', { className: 'h-col', style: { gap: 10 }, children: [
    jsxs('div', { className: 'h-row', children: [
      jsx('h3', { className: 'h-grow', children: 'Your interest card' }),
      jsx('span', { className: 'h-faint h-small', children: published ? 'Published ' + fmtAgo(s.card_published_at) : 'Not published' })
    ] }),
    jsxs('div', { className: 'h-cardpreview', children: [
      jsx(Face, { face: c.agent && c.agent.face, pk: c.agent && c.agent.pk, state: busy ? 'activity: working' : 'activity: idle', size: 44, name: c.agent && c.agent.name }),
      jsxs('div', { className: 'h-grow h-col', style: { gap: 4 }, children: [
        jsxs('div', { children: [jsx('b', { children: c.name || 'No name yet' }), c.agent && c.agent.name ? jsx('span', { className: 'h-faint', children: ' with ' + c.agent.name }) : null] }),
        c.line ? jsx('div', { className: 'h-muted h-small', children: c.line }) : jsx('div', { className: 'h-faint h-small', children: 'No line about you yet (Settings)' }),
        jsx(Chips, { items: c.interests || [] })
      ] })
    ] }),
    raw && jsx('pre', { className: 'h-pre', children: JSON.stringify(c, null, 2) }),
    jsx(Notice, { icon: 'globe', children: 'Publishing puts exactly this on public Nostr relays so others can find you. Anyone can read it. Publish again after you change it.' }),
    jsxs('div', { className: 'h-actions', children: [
      jsx(K.Button, { variant: 'primary', size: 'sm', disabled: busy || !(s.interests || []).length, onClick: publish, children: busy ? 'Publishing…' : published ? 'Publish again' : 'Publish my card' }),
      jsx(K.Button, { variant: 'ghost', size: 'sm', onClick: () => setRaw(!raw), children: raw ? 'Hide exact data' : 'Show exact data' })
    ] })
  ] })
}

// ===== ui/80_app.js =============================================================================

// ---------------------------------------------------------------------------------------------
// the page: left rail (Lobby, rooms), centre (room, Lobby or settings), right rail (people)
// ---------------------------------------------------------------------------------------------

function errorCopy(st) {
  if (st.status === 409) return { title: 'Xenia is open in another Hermes process', body: st.error + ' Close the other one (a second `hermes dashboard` or Desktop gateway on this profile), then retry.' }
  if (st.status === 404) return { title: "Xenia's backend isn't loaded", body: 'Enable the xenia plugin for this profile (plugins.enabled in config.yaml) and restart Hermes so its routes mount.' }
  return { title: 'Xenia could not load', body: st.error || 'The backend did not answer.' }
}

function App(props) {
  const store = props.store
  const st = useStore(store)
  useEffect(() => store.view(), [store])
  const view = useNav()
  const [people, setPeople] = useState(false)
  const go = v => nav().set(v)
  const embedded = !!props.embedded  // Desktop's room tab: the sidebar's Xenia tab is the rail
  const snap = st.snap

  let inner
  if (!snap) {
    inner = st.error
      ? jsx(ErrorPanel, { st, store })
      : jsx('div', { className: 'h-empty', children: [jsx(Face, { pk: 'a1b2c3', state: 'activity: working', size: 48 }, 'f'), jsx('div', { children: 'Lighting the xenia…' }, 't')] })
  } else if (!snap.settings.onboarded) {
    inner = jsx(Onboarding, { store, snap })
  } else {
    const roomId = store.room()
    const room = snap.room && snap.room.id === roomId ? snap.room : null
    const showRoom = view === 'room' && roomId
    let center
    if (view === 'hermes') center = jsx(LineView, { store, snap })
    else if (view === 'settings') center = jsx('div', { className: 'h-scroll', children: jsxs('div', { className: 'h-pane', children: [jsx('h1', { children: 'Settings' }, 'h'), jsx(SettingsForm, { store, snap, inset: true }, 's')] }) })
    else if (showRoom && room) center = jsx(RoomView, { store, snap, room, onPeople: () => setPeople(!people) })
    else if (showRoom) center = jsx('div', { className: 'h-empty', children: 'Opening the room…' })
    else if (view === 'lobby' || !(snap.rooms || []).length) center = jsx(Lobby, { store, snap })
    else center = jsx(Welcome, { snap, onLobby: () => go('lobby') })

    inner = jsx(RoomReactions, { snap, room: showRoom ? room : null, children: jsxs('div', { className: 'h-grid', 'data-people': people ? 'open' : 'closed', 'data-embedded': embedded || undefined, children: [
      !embedded && jsx('nav', { className: 'h-left', 'aria-label': 'Xenia rooms', children: jsx(Rail, { store, snap, view, go, roomId }) }),
      jsxs('main', { className: 'h-center', children: [
        st.error && jsx('div', { style: { padding: '8px 18px 0' }, children: jsx(Notice, { icon: 'warning', role: 'alert', children: errorCopy(st).title + '. Showing the last state we had.' }) }),
        center
      ] }),
      jsx('aside', { className: 'h-right', 'aria-label': 'People', children: view === 'hermes' ? jsx(LineAbout, { snap }) : room && showRoom ? jsx(People, { room, snap }) : jsx(MyAgentCard, { snap }) })
    ] }) })
  }
  return jsxs('div', { className: 'hx h-page', 'data-platform': P.kind, children: [
    P.inlineStyle && jsx('style', { children: CSS }),
    inner
  ] })
}

// Desktop: Xenia's tab in the sidebar strip, next to Sessions and Bots. It's the page's rail; picking
// something opens it in the Xenia tab beside your chats (props.onOpen).
function SideTab(props) {
  const { store, onOpen } = props
  const st = useStore(store)
  const view = useNav()
  const snap = st.snap
  let body
  if (!snap) {
    body = jsx('div', { className: 'h-faint h-small', style: { padding: 8 }, children: st.error ? errorCopy(st).title : 'Lighting the xenia…' })
  } else if (!snap.settings.onboarded) {
    body = jsxs('div', { className: 'h-col', style: { gap: 10, padding: 8 }, children: [
      jsx('div', { className: 'h-small', children: 'Rooms where people and their agents hang out.' }),
      jsx(K.Button, { variant: 'primary', onClick: () => onOpen(), children: 'Set up Xenia' })
    ] })
  } else {
    body = jsx(Rail, { store, snap, view, roomId: view === 'room' ? store.room() : '', go: onOpen })
  }
  return jsxs('nav', { className: 'hx h-tab', 'data-platform': P.kind, 'aria-label': 'Xenia rooms', children: [
    P.inlineStyle && jsx('style', { children: CSS }),
    body
  ] })
}

function ErrorPanel(props) {
  const c = errorCopy(props.st)
  return jsxs('div', { className: 'h-empty', role: 'alert', children: [
    jsx(Face, { pk: 'a1b2c3', state: 'system: error', size: 48 }),
    jsx('b', { children: c.title }),
    jsx('div', { style: { maxWidth: 440 }, children: c.body }),
    jsx(K.Button, { variant: 'secondary', onClick: () => props.store.refresh(), children: 'Try again' })
  ] })
}

function Welcome(props) {
  const a = props.snap.me.agent
  return jsxs('div', { className: 'h-empty', children: [
    jsx(Face, { face: a.face, pk: a.pk, state: a.state, size: 64, name: a.name }),
    jsx('b', { children: (a.name || 'Your agent') + ' is ready' }),
    jsx('div', { children: 'Pick a room on the left, or find people in the Lobby.' }),
    jsx(K.Button, { variant: 'secondary', onClick: props.onLobby, children: 'Open the Lobby' })
  ] })
}

function Rail(props) {
  const { store, snap, view, go, roomId } = props
  const [dialog, setDialog] = useState('')
  const drafts = {}
  for (const d of snap.drafts || []) drafts[d.room] = (drafts[d.room] || 0) + 1
  const waiting = {}
  for (const o of snap.offers || []) if (o.status === 'open' || o.status === 'ready') waiting[o.room] = true
  const a = snap.me.agent
  const line = snap.line || {}
  const open = id => { store.setRoom(id); go('room') }
  return jsxs(Fragment, { children: [
    jsxs('div', { className: 'h-brand', children: [
      jsx(Face, { face: a.face, pk: a.pk, state: a.state, size: 24, name: a.name }),
      jsxs('div', { className: 'h-grow', style: { minWidth: 0 }, children: [
        jsx('b', { children: 'Xenia' }),
        jsx('div', { className: 'h-faint h-tiny h-trunc', children: (snap.me.name || 'You') + ' & ' + (a.name || 'agent') + ' · ' + STATE_LABEL[stateWord(a.state)] })
      ] }),
      jsx(BudgetRing, { budget: snap.budget, size: 16, stroke: 2.2 })
    ] }),
    jsxs('div', { className: 'h-nav', children: [
      jsx(NavRow, { on: view === 'lobby', onClick: () => go('lobby'), icon: 'compass', label: 'Lobby' }),
      jsx(NavRow, { on: view === 'hermes', onClick: () => go('hermes'), icon: 'lock', label: 'Your Hermes',
        badge: line.typing ? 'working' : line.unread > 0 && view !== 'hermes' ? 'unread' : '' }),
      P.kind === 'dashboard'
        ? jsx(NavRow, { on: view === 'settings', onClick: () => go('settings'), icon: 'gear', label: 'Settings' })
        : jsx(NavRow, { onClick: () => P.openSettings(), icon: 'gear', label: 'Settings' })
    ] }),
    jsxs('div', { className: 'h-navhead', children: [
      jsx('span', { className: 'h-sec', children: 'Rooms' }),
      jsxs('span', { className: 'h-row', style: { gap: 2 }, children: [
        jsx(K.Tip, { label: 'Join by code', children: jsx(K.Button, { variant: 'ghost', size: 'icon', 'aria-label': 'Join by code', onClick: () => setDialog('join'), children: jsx(K.Icon, { name: 'link', size: 13 }) }) }),
        jsx(K.Tip, { label: 'New room', children: jsx(K.Button, { variant: 'ghost', size: 'icon', 'aria-label': 'New room', onClick: () => setDialog('new'), children: jsx(K.Icon, { name: 'add', size: 14 }) }) })
      ] })
    ] }),
    jsxs('div', { className: 'h-nav', children: [
      (snap.rooms || []).length === 0 && jsx('div', { className: 'h-faint h-small', style: { padding: '2px 8px' }, children: 'No rooms yet.' }),
      (snap.rooms || []).map(r => jsxs('button', { type: 'button', className: 'h-navrow', 'data-on': view === 'room' && roomId === r.id,
        'aria-current': view === 'room' && roomId === r.id ? 'page' : undefined, onClick: () => open(r.id), children: [
          jsx('span', { className: 'h-hash', children: '#' }),
          jsx('span', { className: 'h-grow h-trunc', style: { fontWeight: r.unread ? 600 : 400 }, children: r.name }),
          (drafts[r.id] || waiting[r.id]) && jsx(K.Tip, { label: waiting[r.id] ? 'Your agent is waiting on you' : 'Draft waiting to send', children: jsx(K.Icon, { name: waiting[r.id] ? 'clock' : 'edit', size: 12 }) }),
          r.unread > 0 && jsx('span', { className: 'h-dot', 'aria-label': r.unread + ' unread' }),
          jsx('span', { className: 'h-count', title: r.online + ' online', children: r.online || '' })
        ] }, r.id))
    ] }),
    dialog === 'new' && jsx(NewRoomDialog, { store, snap, onClose: () => setDialog(''), onDone: id => { setDialog(''); open(id) } }),
    dialog === 'join' && jsx(JoinDialog, { store, onClose: () => setDialog(''), onDone: id => { setDialog(''); open(id) } })
  ] })
}

function NavRow(props) {
  return jsxs('button', { type: 'button', className: 'h-navrow', 'data-on': !!props.on, onClick: props.onClick, children: [
    jsx(K.Icon, { name: props.icon, size: 14 }), jsx('span', { className: 'h-grow', children: props.label }),
    props.badge === 'unread' && jsx('span', { className: 'h-dot', 'aria-label': 'new reply' }),
    props.badge === 'working' && jsx('span', { className: 'h-faint h-tiny', children: 'working' })
  ] })
}

function NewRoomDialog(props) {
  const { store, snap } = props
  const [name, setName] = useState('')
  const [about, setAbout] = useState('')
  const [interests, setInterests] = useState(() => (snap.settings.interests || []).slice(0, 3))
  const [busy, setBusy] = useState(false)
  const create = async () => {
    setBusy(true)
    try { const meta = await store.post('/rooms', { name, about, interests }, 'Room created'); props.onDone(meta.id) } catch (_) { setBusy(false) }
  }
  return jsx(Modal, { open: true, onClose: props.onClose, title: 'New room',
    description: 'Rooms are public: they are listed in the Lobby under their interests, and anyone with the code can join.',
    footer: [
      jsx(K.Button, { variant: 'ghost', onClick: props.onClose, children: 'Cancel' }, 'c'),
      jsx(K.Button, { variant: 'primary', disabled: busy || !name.trim(), onClick: create, children: busy ? 'Creating…' : 'Create room' }, 'k')
    ],
    children: jsxs('div', { className: 'h-col', style: { gap: 12 }, children: [
      jsx(Field, { label: 'Name', id: 'h-nr-name', children: jsx(K.Input, { id: 'h-nr-name', value: name, maxLength: 40, autoFocus: true, placeholder: 'shader club', onChange: e => setName(e.target.value) }) }),
      jsx(Field, { label: 'What it is about', id: 'h-nr-about', children: jsx(K.Input, { id: 'h-nr-about', value: about, maxLength: 200, placeholder: 'pixels, shaders, glitch art', onChange: e => setAbout(e.target.value) }) }),
      jsx(Field, { label: 'Interests', id: 'h-nr-int', children: jsx(InterestInput, { id: 'h-nr-int', value: interests, onChange: setInterests }) })
    ] }) })
}

function JoinDialog(props) {
  const [code, setCode] = useState('')
  const [busy, setBusy] = useState(false)
  const join = async () => {
    setBusy(true)
    try { const meta = await props.store.post('/rooms/join', { room: code.trim() }); props.onDone(meta.id) } catch (_) { setBusy(false) }
  }
  return jsx(Modal, { open: true, onClose: props.onClose, title: 'Join by code', description: 'Paste a code like xenia:203f22bcfd1b4b2f.',
    footer: [
      jsx(K.Button, { variant: 'ghost', onClick: props.onClose, children: 'Cancel' }, 'c'),
      jsx(K.Button, { variant: 'primary', disabled: busy || !code.trim(), onClick: join, children: busy ? 'Joining…' : 'Join' }, 'j')
    ],
    children: jsx(K.Input, { value: code, autoFocus: true, placeholder: 'xenia:…', 'aria-label': 'Room code', onChange: e => setCode(e.target.value),
      onKeyDown: e => { if (e.key === 'Enter') join() } }) })
}

// ---- Desktop status bar chip ------------------------------------------------------------------

function StatusChip(props) {
  const st = useStore(props.store)
  const snap = st.snap
  if (!snap || !snap.settings || !snap.settings.onboarded) {
    return jsx(K.Tip, { label: st.error ? 'Xenia: ' + errorCopy(st).title : 'Open Xenia', children: jsxs('button', { type: 'button', className: 'hx h-statuschip', onClick: props.onOpen, children: [
      jsx(K.Icon, { name: 'home', size: 12 }), 'Xenia'] }) })
  }
  const a = snap.me.agent
  const w = stateWord(a.state)
  const waiting = (snap.offers || []).some(o => o.status === 'open' || o.status === 'ready') || (snap.drafts || []).length > 0
  const label = (a.name || 'Your agent') + ' · ' + STATE_LABEL[w] + (a.note ? ' (' + a.note + ')' : '') + ' · ' +
    fmtTokens(snap.budget.used) + ' of ' + fmtTokens(snap.budget.limit) + ' tokens today' + (waiting ? ' · waiting on you' : '')
  return jsx(K.Tip, { label, children: jsxs('button', { type: 'button', className: 'hx h-statuschip', 'aria-label': 'Open Xenia: ' + label, onClick: props.onOpen, children: [
    jsx(Face, { face: a.face, pk: a.pk, state: waiting ? 'system: waiting' : a.state, size: 15, name: a.name }),
    jsx('span', { children: STATE_LABEL[w] }),
    jsx(BudgetRing, { budget: snap.budget, size: 11, stroke: 1.8 })
  ] }) })
}

// ===== platform ================================================================================

  // ---------------------------------------------------------------------------------------------
  // dashboard platform: fetch, timers, toasts, clipboard, storage, and the kit adapter. The
  // dashboard SDK has fewer components than Desktop, so a few are plain elements styled with the
  // dashboard's own theme variables.
  // ---------------------------------------------------------------------------------------------

  const toasts = { list: [], fns: new Set(), seq: 0 }
  function pushToast(kind, message) {
    const id = ++toasts.seq
    toasts.list = toasts.list.concat([{ id, kind, message }]).slice(-3)
    toasts.fns.forEach(fn => fn(toasts.list))
    window.setTimeout(() => {
      toasts.list = toasts.list.filter(t => t.id !== id)
      toasts.fns.forEach(fn => fn(toasts.list))
    }, kind === 'error' ? 7000 : 4000)
  }

  const P = {
    kind: 'dashboard',
    inlineStyle: true,
    rest(path, opts) {
      const o = opts || {}
      const init = o.method && o.method !== 'GET'
        ? { method: o.method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(o.body || {}) }
        : undefined
      return SDK.fetchJSON('/api/plugins/xenia' + path, init)
    },
    toast: pushToast,
    copy(text) {
      try { return navigator.clipboard.writeText(text).then(() => true, () => false) } catch (_) { return Promise.resolve(false) }
    },
    // the shared animation loop: one rAF chain, parked whenever idle() says nothing moves
    loop(draw, idle) {
      let frame = 0
      const tick = now => { frame = 0; draw(now); if (!idle()) frame = window.requestAnimationFrame(tick) }
      return {
        wake() { if (!frame) frame = window.requestAnimationFrame(tick) },
        dispose() { if (frame) window.cancelAnimationFrame(frame); frame = 0 }
      }
    },
    setTimeout(fn, ms) { const t = window.setTimeout(fn, ms); return () => window.clearTimeout(t) },
    setInterval(fn, ms) { const t = window.setInterval(fn, ms); return () => window.clearInterval(t) },
    listen(target, type, fn) { target.addEventListener(type, fn); return () => target.removeEventListener(type, fn) },
    prefs: {
      get(k, d) { try { const v = window.localStorage.getItem('xenia.' + k); return v == null ? d : JSON.parse(v) } catch (_) { return d } },
      set(k, v) { try { window.localStorage.setItem('xenia.' + k, JSON.stringify(v)) } catch (_) { /* private mode */ } }
    },
    // no composer to hand a prompt to from the browser: the caller shows it with a Copy button
    openBuild() { return Promise.resolve(false) },
    openSettings() {}
  }

  // a handful of line icons, drawn on a 16px grid with the current text colour
  const ICONS = {
    add: 'M8 3v10M3 8h10',
    link: 'M6.5 9.5l3-3M7 4.5l1-1a2.8 2.8 0 0 1 4 4l-1 1M9 11.5l-1 1a2.8 2.8 0 0 1-4-4l1-1',
    compass: 'M8 1.8a6.2 6.2 0 1 0 0 12.4A6.2 6.2 0 0 0 8 1.8zM10.6 5.4L9.2 9.2 5.4 10.6 6.8 6.8z',
    gear: 'M8 5.6a2.4 2.4 0 1 0 0 4.8 2.4 2.4 0 0 0 0-4.8zM8 1.5v1.6M8 12.9v1.6M1.5 8h1.6M12.9 8h1.6M3.4 3.4l1.1 1.1M11.5 11.5l1.1 1.1M3.4 12.6l1.1-1.1M11.5 4.5l1.1-1.1',
    refresh: 'M13 4v3h-3M3 12V9h3M12.4 7A4.6 4.6 0 0 0 4 5.2M3.6 9a4.6 4.6 0 0 0 8.4 1.8',
    copy: 'M5.5 5.5h7v7h-7zM3.5 10.5v-7h7',
    play: 'M5 3.5l7 4.5-7 4.5z',
    send: 'M2.5 8L13.5 3 10 13.5 7.7 8.6zM7.7 8.6L13.5 3',
    game: 'M5 5.5h6a3 3 0 0 1 3 3v.5a2.5 2.5 0 0 1-4.4 1.6L9 10H7l-.6.6A2.5 2.5 0 0 1 2 9v-.5a3 3 0 0 1 3-3zM5 7.2v2M4 8.2h2M10.5 8h.01M11.8 9h.01',
    shield: 'M8 1.8l5 2v3.7c0 3-2.2 5.6-5 6.7-2.8-1.1-5-3.7-5-6.7V3.8z',
    warning: 'M8 2l6.2 11H1.8zM8 6.5v3M8 11.3h.01',
    globe: 'M8 1.8a6.2 6.2 0 1 0 0 12.4A6.2 6.2 0 0 0 8 1.8zM1.8 8h12.4M8 1.8c1.7 1.8 2.5 3.9 2.5 6.2S9.7 12.4 8 14.2C6.3 12.4 5.5 10.3 5.5 8S6.3 3.6 8 1.8z',
    edit: 'M10.5 2.5l3 3-8 8H2.5v-3zM9 4l3 3',
    organization: 'M5.5 6.5a2 2 0 1 0 0-4 2 2 0 0 0 0 4zM2 13c0-2.2 1.6-4 3.5-4S9 10.8 9 13M11 7a1.7 1.7 0 1 0 0-3.4A1.7 1.7 0 0 0 11 7zM10.5 9c1.9 0 3.5 1.6 3.5 4',
    'sign-out': 'M6 2.5H3v11h3M10 5l3 3-3 3M13 8H6',
    clock: 'M8 1.8a6.2 6.2 0 1 0 0 12.4A6.2 6.2 0 0 0 8 1.8zM8 4.5V8l2.3 1.5',
    home: 'M2.5 7.5L8 2.5l5.5 5M4 6.5v7h8v-7M6.8 13.5V10h2.4v3.5',
    close: 'M4 4l8 8M12 4l-8 8',
    lock: 'M4.5 7.5h7v6h-7zM6 7.5V5.5a2 2 0 0 1 4 0v2',
    reply: 'M6.5 4L3 7.5 6.5 11M3 7.5h6.5a3.5 3.5 0 0 1 3.5 3.5v1'
  }

  function Icon(props) {
    const s = props.size || 14
    return jsx('svg', { width: s, height: s, viewBox: '0 0 16 16', fill: 'none', stroke: 'currentColor', strokeWidth: 1.4,
      strokeLinecap: 'round', strokeLinejoin: 'round', 'aria-hidden': true, className: props.spinning ? 'h-spin' : undefined,
      style: { flex: 'none' }, children: jsx('path', { d: ICONS[props.name] || ICONS.add }) })
  }

  // The dashboard's Button is the theme's own (mono, arc border). Icon buttons are plain and quiet.
  function Button(props) {
    const { variant, size, className, children } = props
    const rest = Object.assign({}, props)
    delete rest.variant; delete rest.size; delete rest.className; delete rest.children
    if (size === 'icon' || variant === 'ghost') {
      return jsx('button', Object.assign({ type: 'button', className: cx('h-dbtn', size === 'icon' && 'h-dbtn-icon', className) }, rest, { children }))
    }
    return jsx(C.Button, Object.assign({ className: cx(size === 'sm' && 'h-dbtn-sm', className), outlined: variant === 'secondary' || variant === 'outline',
      destructive: variant === 'danger' }, rest, { children }))
  }

  function Dialog(props) {
    return jsx(C.Dialog, { open: !!props.open, onOpenChange: v => { if (!v) props.onClose() }, children:
      jsx(C.DialogContent, { style: props.wide ? { maxWidth: 680, width: 'calc(100vw - 32px)' } : { width: 'calc(100vw - 32px)', maxWidth: 460 },
        children: jsxs('div', { className: 'hx h-col', style: { gap: 14, padding: 20 }, children: [
          jsxs(C.DialogHeader, { style: { padding: 0 }, children: [
            jsx(C.DialogTitle, { children: props.title }),
            props.description && jsx(C.DialogDescription, { children: props.description })
          ] }),
          props.children,
          props.footer && jsx('div', { className: 'h-actions', style: { justifyContent: 'flex-end' }, children: props.footer })
        ] }) }) })
  }

  function Toggle(props) {
    return jsxs('label', { className: 'h-row', style: { alignItems: 'flex-start', gap: 10, cursor: 'pointer' }, children: [
      jsx('input', { type: 'checkbox', checked: !!props.checked, onChange: e => props.onChange(e.target.checked),
        style: { marginTop: 3, accentColor: 'var(--h-accent)' } }),
      jsxs('span', { className: 'h-col', style: { gap: 2 }, children: [
        jsx('span', { style: { fontWeight: 600 }, children: props.label }),
        props.description && jsx('span', { className: 'h-faint h-small', children: props.description })
      ] })
    ] })
  }

  const K = {
    Button,
    Input: C.Input,
    Dialog,
    Icon,
    Toggle,
    Tip: props => jsx('span', { title: typeof props.label === 'string' ? props.label : undefined, style: { display: 'inline-flex' }, children: props.children }),
    // a shared toy: opaque origin (no allow-same-origin), scripts only
    Toy: props => jsx('iframe', { title: props.title, sandbox: 'allow-scripts', srcDoc: withCsp(props.html), referrerPolicy: 'no-referrer' })
  }

  const DASH_CSS = `
.h-dbtn{display:inline-flex;align-items:center;justify-content:center;gap:6px;border:0;background:transparent;color:var(--h-fg2);border-radius:6px;padding:4px 8px;cursor:pointer;font-size:12px;white-space:nowrap}
.h-dbtn:hover:not(:disabled){background:var(--h-hover);color:var(--h-fg)}
.h-dbtn:disabled{opacity:.45;cursor:default}
.h-dbtn-icon{width:28px;height:28px;padding:0}
.h-dbtn-sm{font-size:11px!important;padding:4px 10px!important;height:auto!important}
.hx button svg:not(:only-child){margin-right:6px}
.h-spin{animation:h-spin 1s linear infinite}
@keyframes h-spin{to{transform:rotate(360deg)}}
.h-toasts{position:fixed;right:20px;bottom:20px;display:flex;flex-direction:column;gap:8px;z-index:60;max-width:360px}
.h-toast{border:1px solid var(--h-line2);background:var(--h-card);color:var(--h-fg);padding:10px 14px;border-radius:10px;font-size:12.5px;box-shadow:0 12px 32px -16px var(--h-shadow)}
.h-toast[data-kind=error]{border-color:color-mix(in srgb,var(--h-bad) 60%,transparent)}
`

  function Toasts() {
    const [list, setList] = useState(toasts.list)
    useEffect(() => { toasts.fns.add(setList); return () => toasts.fns.delete(setList) }, [])
    return jsx('div', { className: 'hx h-toasts', role: 'status', 'aria-live': 'polite', children: list.map(t =>
      jsx(ToastItem, { t }, t.id)) })
  }
  function ToastItem(props) {
    const ref = useEnter(true)
    return jsx('div', { ref, className: 'h-toast', 'data-kind': props.t.kind, children: props.t.message })
  }

  // The tab mounts inside the dashboard's scrolling <main>. Size the page to the space left
  // below its top edge so the room's header and composer stay put and only the timeline scrolls.
  function useFitHeight() {
    const ref = useRef(null)
    const [h, setH] = useState(0)
    useEffect(() => {
      const fit = () => {
        const el = ref.current
        if (!el) return
        const top = el.getBoundingClientRect().top
        setH(Math.max(480, Math.floor(window.innerHeight - Math.max(0, top) - 24)))
      }
      fit()
      const t = window.setTimeout(fit, 300)
      window.addEventListener('resize', fit)
      return () => { window.clearTimeout(t); window.removeEventListener('resize', fit) }
    }, [])
    return [ref, h]
  }

  let store = null
  function XeniaTab() {
    if (!store) store = createStore()
    useEffect(() => { store.start(); return () => store.stop() }, [])
    const [ref, h] = useFitHeight()
    return jsxs('div', { ref, className: 'h-dashframe', style: h ? { height: h } : { height: '75vh' }, children: [
      jsx('style', { children: DASH_CSS }),
      jsx(App, { store }),
      jsx(Toasts, {})
    ] })
  }

  window.__HERMES_PLUGINS__.register('xenia', XeniaTab)
})()
